// ---------- V0.5 REALISM OVERRIDES ----------
// management/runtime state is initialized at startup (Safari-safe).

function aircraftShape(spec,liv,detail={},logo='SKYLINE',mini=false){
  const code=(spec.icao||'').toUpperCase(),cat=(spec.category||'').toLowerCase();
  const turb=cat.includes('turboprop'),heli=cat.includes('hélic')||cat.includes('helic');
  const four=code==='A388'||code.startsWith('B74')||code==='A346';
  const primary=liv.primary||'#0b4b78',secondary=liv.secondary||'#f3f7fb',accent=liv.accent||'#42d392';
  const tail=detail.tail_color||primary,eng=detail.engine_color||primary,belly=detail.belly_color||'#d9e1e8',nose=detail.nose_color||secondary;
  if(heli)return `<svg class="${mini?'aircraft-mini-svg':'aircraft-svg'}" viewBox="0 0 900 330"><g><ellipse cx="430" cy="175" rx="205" ry="52" fill="${secondary}" stroke="#17242f" stroke-width="5"/><path d="M250 170 L85 130 L65 147 L235 192Z" fill="${primary}"/><path d="M610 170 L830 110 L846 130 L627 195Z" fill="${primary}"/><path d="M605 163 L770 55 L790 70 L640 186Z" fill="${tail}"/><rect x="410" y="52" width="14" height="240" rx="7" fill="#cbd4dc"/><rect x="225" y="165" width="410" height="9" rx="4" fill="${accent}"/><text x="330" y="185" font-size="32" font-weight="800" fill="${primary}">${logo}</text></g></svg>`;
  const bodyY=162,bodyH=turb?54:(code==='A388'?78:62),wingY=bodyY+bodyH*.48;
  let engines='';const xs=four?[365,440,520,595]:[410,550];xs.forEach((x,i)=>{engines+=turb?`<g transform="translate(${x} ${wingY+(i%2?40:-40)})"><ellipse rx="21" ry="13" fill="${eng}"/><line x1="-34" x2="34" stroke="#dfe8ed" stroke-width="5" transform="rotate(${i%2?20:-20})"/></g>`:`<ellipse cx="${x}" cy="${wingY+(i%2?43:-43)}" rx="28" ry="15" fill="${eng}" stroke="#17242f" stroke-width="3"/>`});
  const windows=Array.from({length:22},(_,i)=>`<rect x="${250+i*19}" y="${bodyY+16}" width="9" height="5" rx="2" fill="#1c3447" opacity=".85"/>`).join('');
  const logoX=250+Number(detail.logo_position||.35)*250,logoScale=Number(detail.logo_scale||1);
  return `<svg class="${mini?'aircraft-mini-svg':'aircraft-svg'}" viewBox="0 0 900 330" aria-label="${spec.manufacturer||''} ${spec.name||''}"><defs><linearGradient id="fus${code}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${nose}"/><stop offset=".72" stop-color="${secondary}"/><stop offset="1" stop-color="${belly}"/></linearGradient></defs><g><path d="M120 ${bodyY+bodyH/2} Q165 ${bodyY-8} 250 ${bodyY} L700 ${bodyY} Q790 ${bodyY+5} 820 ${bodyY+bodyH/2} Q785 ${bodyY+bodyH-3} 700 ${bodyY+bodyH} L250 ${bodyY+bodyH} Q165 ${bodyY+bodyH+8} 120 ${bodyY+bodyH/2}Z" fill="url(#fus${code})" stroke="#17242f" stroke-width="4"/><path d="M665 ${bodyY+4} L735 ${bodyY-105} L766 ${bodyY-99} L728 ${bodyY+26}Z" fill="${tail}" stroke="#17242f" stroke-width="4"/><path d="M420 ${wingY} L205 ${wingY-95} L190 ${wingY-80} L385 ${wingY+18}Z" fill="#dbe4ea" stroke="#17242f" stroke-width="4"/><path d="M505 ${wingY} L720 ${wingY+95} L735 ${wingY+80} L540 ${wingY-18}Z" fill="#dbe4ea" stroke="#17242f" stroke-width="4"/>${engines}${windows}<path d="M185 ${bodyY+bodyH-12} Q430 ${bodyY+bodyH+4} 725 ${bodyY+bodyH-10}" fill="none" stroke="${accent}" stroke-width="10" stroke-linecap="round"/><text x="${logoX}" y="${bodyY+bodyH*.67}" font-size="${Math.round(30*logoScale)}" font-weight="900" letter-spacing="4" fill="${primary}">${logo}</text><text x="690" y="${bodyY+bodyH*.64}" font-size="13" fill="#344958">${code}</text></g></svg>`;
}

function renderFleet(){if(!STATE)return;const b=$('#fleetList');if(!STATE.aircraft.length){b.innerHTML='<div class="empty-state"><b>Ta flotte est vide</b><span>Achète ou loue ton premier appareil.</span><button class="primary" data-go-market>Acheter un aéronef</button></div>';b.querySelector('[data-go-market]')?.addEventListener('click',()=>nav('market'));return}b.innerHTML=STATE.aircraft.map(a=>`<article class="fleet-item"><div class="aircraft-visual-card">${aircraftShape(a.spec,a.livery,a.livery_detail,STATE.profile.logo_text,true)}</div><div><b>${a.tail} · ${a.spec.manufacturer} ${a.spec.name}</b><small>${a.home_hub} · État ${a.condition}% · ${a.flight?a.flight.status:'Disponible'}</small><div class="route-kpi"><span>Wi‑Fi ${a.service.wifi}/10</span><span>Repas ${a.service.meals}/10</span><span>Confort ${a.service.comfort}/10</span></div></div><div class="fleet-actions">${a.flight?`<button class="mini-btn" onclick="openCockpit(${a.id})">Cockpit</button>`:''}<button class="mini-btn" onclick="openService(${a.id})">Service à bord</button><button class="mini-btn" onclick="editLivery(${a.id})">Livrée</button></div></article>`).join('');}

window.openService=async id=>{try{const a=STATE.aircraft.find(x=>x.id===id),d=await api(`/api/aircraft/${id}/service`);$('#serviceModalContent').innerHTML=`<p class="eyebrow">${a.tail}</p><h2>Produit cabine & service à bord</h2><p class="muted">Ces améliorations peuvent être commandées même pendant une rotation. Elles augmentent l’attractivité mais aussi le coût de service.</p><div class="service-grid">${Object.entries(d.upgrades).map(([k,x])=>`<div class="service-card"><header><b>${x.label}</b><span>${x.level}/${x.max}</span></header><div class="progress"><i style="width:${x.level/x.max*100}%"></i></div><p>Prochain investissement : ${x.level>=x.max?'MAX':money(x.price)}</p><button class="secondary" data-svc="${k}" ${x.level>=x.max?'disabled':''}>${x.level?'Améliorer':'Installer'}</button></div>`).join('')}</div>`;$('#serviceModal').classList.add('open');$('#serviceModalContent').querySelectorAll('[data-svc]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/aircraft/${id}/service/upgrade`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:btn.dataset.svc})});toast('Produit cabine amélioré');await loadState();openService(id)}catch(e){toast(e.message)}}))}catch(e){toast(e.message)}};

window.editLivery=id=>{const a=STATE.aircraft.find(x=>x.id===id);if(!a)return;const d=a.livery_detail||{};const logo=STATE.profile.logo_text||STATE.user.company_name;$('#liveryModalContent').innerHTML=`<p class="eyebrow">LIVERY STUDIO · ${a.tail}</p><h2>${a.spec.manufacturer} ${a.spec.name}</h2><div class="livery-studio"><div class="livery-canvas" id="liveLiveryCanvas"></div><div class="livery-controls"><div class="color-grid"><label>Fuselage<input type="color" id="ls" value="${a.livery.secondary}"></label><label>Marque<input type="color" id="lp" value="${a.livery.primary}"></label><label>Accent<input type="color" id="la" value="${a.livery.accent}"></label><label>Dérive<input type="color" id="ltail" value="${d.tail_color||a.livery.primary}"></label><label>Moteurs<input type="color" id="leng" value="${d.engine_color||a.livery.primary}"></label><label>Ventre<input type="color" id="lbelly" value="${d.belly_color||'#d9e1e8'}"></label></div><label>Style<select id="lstyle"><option value="swoosh">Swoosh</option><option value="tail">Dérive forte</option><option value="stripe">Bande</option><option value="minimal">Minimal</option><option value="retro">Rétro</option></select></label><label>Taille logo<input type="range" min="0.5" max="2" step="0.05" id="lscale" value="${d.logo_scale||1}"></label><label>Position logo<input type="range" min="0.15" max="0.75" step="0.02" id="lpos" value="${d.logo_position||.35}"></label><label>Nom de la livrée<input id="lname" value="${a.livery.name||'Standard'}"></label><button class="primary" id="saveLivery">Appliquer à ${a.tail}</button></div></div>`;$('#lstyle').value=d.stripe_style||a.livery.template||'swoosh';const redraw=()=>{$('#liveLiveryCanvas').innerHTML=aircraftShape(a.spec,{primary:$('#lp').value,secondary:$('#ls').value,accent:$('#la').value},{tail_color:$('#ltail').value,engine_color:$('#leng').value,belly_color:$('#lbelly').value,nose_color:$('#ls').value,logo_scale:Number($('#lscale').value),logo_position:Number($('#lpos').value)},logo)};['lp','ls','la','ltail','leng','lbelly','lstyle','lscale','lpos'].forEach(x=>$('#'+x).addEventListener('input',redraw));redraw();$('#liveryModal').classList.add('open');$('#saveLivery').addEventListener('click',async()=>{try{await api(`/api/aircraft/${id}/livery`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({primary:$('#lp').value,secondary:$('#ls').value,accent:$('#la').value,tail_color:$('#ltail').value,engine_color:$('#leng').value,belly_color:$('#lbelly').value,nose_color:$('#ls').value,stripe_style:$('#lstyle').value,name:$('#lname').value,logo_scale:Number($('#lscale').value),logo_position:Number($('#lpos').value)})});toast('Livrée appliquée');$('#liveryModal').classList.remove('open');await loadState()}catch(e){toast(e.message)}})};

function renderRoutes(){if(!STATE)return;$('#routeOrigin').innerHTML=STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('');const used=new Set(STATE.routes.map(r=>r.aircraft_id)),free=STATE.aircraft.filter(a=>!used.has(a.id));$('#routeAircraft').innerHTML='<option value="">Choisir…</option>'+free.map(a=>`<option value="${a.id}">${a.tail} · ${a.spec.name}</option>`).join('');const list=$('#routesList');if(!STATE.routes.length){list.innerHTML='<div class="empty-state"><b>Aucune rotation</b><span>Crée ta première ligne avec un avion libre.</span></div>';return}list.innerHTML=STATE.routes.map(r=>`<div class="list-row"><div><b>${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${r.tail} · ${r.model} · ${r.flight.status} · temps réel × 0,33</small><div class="route-kpi"><span>Charge ${Math.round((r.economy?.load_factor||0)*100)}%</span><span>Prix Éco ${money(r.pricing.economy_price)}</span><span>Profit/vol ${money(r.economy?.profit||0)}</span><span>${r.crew?.contracted?`${r.crew.contracted} crew contractuel(s)`:'Équipage interne OK'}</span></div>${r.partner?`<small class="partner-line">${r.partner.airline} assure ${r.partner.from} → ${r.partner.to}</small>`:''}</div><div class="list-actions"><button class="mini-btn" onclick="openPricing(${r.id})">Prix & demande</button><button class="mini-btn" onclick="openCockpit(${r.aircraft_id})">Cockpit</button><button class="mini-btn danger-btn" onclick="deleteRoute(${r.id})">Fermer</button></div></div>`).join('')}

window.openPricing=async id=>{try{const r=STATE.routes.find(x=>x.id===id),d=await api(`/api/routes/${id}/pricing`),s=d.settings,e=d.estimate;$('#pricingModalContent').innerHTML=`<p class="eyebrow">REVENUE MANAGEMENT · ${r.origin_airport.code} → ${r.destination_airport.code}</p><h2>Prix, affluence & rentabilité</h2><div class="estimate-grid"><div><small>Demande estimée</small><b>${Math.round(e.load_factor*100)}%</b></div><div><small>Passagers</small><b>${fmt(e.passengers)}</b></div><div><small>Chiffre d’affaires</small><b>${money(e.revenue)}</b></div><div><small>Profit par vol</small><b class="${e.profit>=0?'profit-pos':'profit-neg'}">${money(e.profit)}</b></div></div><div class="pricing-grid"><label>Economy (€)<input type="number" id="pe" value="${Math.round(s.economy_price)}"></label><label>Premium Economy (€)<input type="number" id="pp" value="${Math.round(s.premium_price)}"></label><label>Business (€)<input type="number" id="pb" value="${Math.round(s.business_price)}"></label><label>First (€)<input type="number" id="pf" value="${Math.round(s.first_price)}"></label><label>Bagage optionnel (€)<input type="number" id="pbag" value="${Math.round(s.baggage_fee)}"></label><label>Surbooking (%)<input type="number" id="pover" min="0" max="15" value="${s.overbooking_percent}"></label></div><p class="muted">Le moteur recalcule la demande selon le prix, la réputation, le marketing, le produit cabine, l’aéroport et les partenariats.</p><button class="primary" id="savePricing">Enregistrer les tarifs</button>`;$('#pricingModal').classList.add('open');$('#savePricing').addEventListener('click',async()=>{try{await api(`/api/routes/${id}/pricing`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({economy_price:Number($('#pe').value),premium_price:Number($('#pp').value),business_price:Number($('#pb').value),first_price:Number($('#pf').value),baggage_fee:Number($('#pbag').value),overbooking_percent:Number($('#pover').value)})});toast('Tarifs enregistrés');$('#pricingModal').classList.remove('open');await loadState()}catch(e){toast(e.message)}})}catch(e){toast(e.message)}};

// Actual gates and parking positions on the satellite hub map.
async function loadHubSurfaceNetwork(){if(!hubMap||!HUBSTATE)return;['hub-aprons','hub-taxiways','hub-osm-runways','hub-gates'].forEach(id=>hubMap.getLayer(id)&&hubMap.removeLayer(id));if(hubMap.getSource('hub-surface'))hubMap.removeSource('hub-surface');hubSurfaceLines=[];hubGatePoints=[];hubSurfaceFeatures=[];clearMarkers(hubAssetMarkers);try{const geo=await api('/api/hub/'+encodeURIComponent(activeHubIdent)+'/surface-network');hubSurfaceSource=geo.source||'surface';hubSurfaceFeatures=geo.features||[];hubMap.addSource('hub-surface',{type:'geojson',data:geo});hubMap.addLayer({id:'hub-aprons',type:'fill',source:'hub-surface',filter:['==',['get','kind'],'apron'],paint:{'fill-color':'#4fa3c7','fill-opacity':.07,'fill-outline-color':'#8bdcff'}});hubMap.addLayer({id:'hub-taxiways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'taxiway'],paint:{'line-color':'#f2c94c','line-width':['interpolate',['linear'],['zoom'],11,.7,17,3.2],'line-opacity':.78}});hubMap.addLayer({id:'hub-osm-runways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'runway'],paint:{'line-color':'#9fe8ff','line-width':['interpolate',['linear'],['zoom'],11,1,17,5],'line-opacity':.7}});hubMap.addLayer({id:'hub-gates',type:'circle',source:'hub-surface',filter:['in',['get','kind'],['literal',['gate','parking_position']]],paint:{'circle-radius':2,'circle-color':'#fff','circle-opacity':.25}});hubSurfaceFeatures.forEach(f=>{const k=f.properties?.kind;if(f.geometry?.type==='LineString'&&(k==='taxiway'||k==='runway'))hubSurfaceLines.push({kind:k,coords:f.geometry.coordinates,feature:f});if(f.geometry?.type==='Point'&&(k==='gate'||k==='parking_position'))hubGatePoints.push({coords:f.geometry.coordinates,feature:f})});drawHubAssets();$('#hubMeta').textContent+=` · réseau sol ${hubSurfaceSource.includes('OpenStreetMap')?'OSM réel':'pistes connues'}`}catch(e){console.warn(e)}}
function assetOwned(key){return (HUBSTATE?.assets||[]).some(x=>x.asset_key===key)}
function drawHubAssets(){clearMarkers(hubAssetMarkers);if(!HUBSTATE)return;const candidates=[];hubGatePoints.slice(0,160).forEach(x=>candidates.push(x.feature));hubSurfaceFeatures.filter(f=>f.properties?.kind==='runway'&&f.geometry?.type==='LineString').forEach(f=>candidates.push(f));candidates.forEach((f,i)=>{const kind=f.properties?.kind,key=f.properties?.asset_key||`${kind}:${i}`,name=f.properties?.name||(`${kind==='gate'?'Porte':'Stand'} ${i+1}`);let pt;if(f.geometry.type==='Point')pt=f.geometry.coordinates;else pt=pointOnLine(f.geometry.coordinates,.5);if(!pt)return;const owned=assetOwned(key),el=document.createElement('button');el.className=`hub-asset-marker ${owned?'owned':'locked'} ${kind==='runway'?'runway':''}`;el.textContent=owned?'✓':(kind==='gate'?'G':kind==='parking_position'?'P':'RWY');el.title=`${owned?'Acquis':'Verrouillé'} · ${name}`;el.addEventListener('click',()=>inspectHubAsset({key,kind,name,pt,owned}));hubAssetMarkers.push(new maplibregl.Marker({element:el}).setLngLat(pt).addTo(hubMap))})}
function inspectHubAsset(x){const price=x.kind==='gate'?3200000:x.kind==='parking_position'?1750000:18000000;$('#hubInspectorContent').innerHTML=`<span class="inspector-tag">INFRASTRUCTURE RÉELLE</span><h2 class="inspector-title">${x.name||x.kind}</h2><p class="muted">${x.kind==='runway'?'Droit d’exploitation / participation à la capacité de piste.':'Emplacement identifié sur le réseau aéroportuaire. Il reste grisé et verrouillé tant qu’il n’est pas acquis.'}</p><div class="stat-row"><span>État</span><b>${x.owned?'ACQUIS':'🔒 VERROUILLÉ'}</b></div><div class="stat-row"><span>Coût</span><b>${x.owned?'—':money(price)}</b></div>${x.owned?'':'<button class="primary" id="buyAsset">Acheter / débloquer</button>'}`;$('#hubInspector').classList.add('open');$('#buyAsset')?.addEventListener('click',async()=>{try{await api('/api/hub/asset/buy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ident:activeHubIdent,asset_key:x.key,kind:x.kind,name:x.name,lon:x.pt[0],lat:x.pt[1]})});toast('Infrastructure débloquée');HUBSTATE=await api('/api/hub/'+encodeURIComponent(activeHubIdent));drawHubAssets();renderHeader();$('#hubInspector').classList.remove('open')}catch(e){toast(e.message)}})}
$('#toggleAssets')?.addEventListener('click',e=>{e.currentTarget.classList.toggle('active');const on=e.currentTarget.classList.contains('active');hubAssetMarkers.forEach(m=>m.getElement().style.display=on?'grid':'none')});
function drawHubUpgrades(){clearMarkers(hubUpgradeMarkers);HUBSTATE.nodes.forEach(n=>{const el=document.createElement('button');el.className='hub-upgrade-marker '+n.state;el.textContent=n.state==='locked'?'🔒':n.level?String(n.level):'+';el.title=n.name;el.addEventListener('click',()=>inspectUpgrade(n));hubUpgradeMarkers.push(new maplibregl.Marker({element:el}).setLngLat([n.lon,n.lat]).addTo(hubMap))})}

function groundPath(kind,seed){const taxi=hubSurfaceLines.filter(x=>x.kind==='taxiway'),runways=hubSurfaceLines.filter(x=>x.kind==='runway');if(kind==='plane'&&runways.length&&seed%3===0)return runways[seed%runways.length];return taxi.length?taxi[seed%taxi.length]:(runways.length?runways[seed%runways.length]:null)}
function animateAlongNetwork(marker,seed,kind='vehicle',knots=15){const path=groundPath(kind,seed);if(!path)return;const speed=Math.max(.000003,knots/3600/60),start=performance.now();function tick(t){if(!hubTrafficMarkers.includes(marker))return;let p=((t-start)*speed+(seed*.11))%2;if(p>1)p=2-p;const pt=pointOnLine(path.coords,p);if(pt)marker.setLngLat(pt);requestAnimationFrame(tick)}requestAnimationFrame(tick)}
async function refreshHubTraffic(){
  if(!HUBSTATE||!hubMap)return;
  clearMarkers(hubTrafficMarkers);
  const a=HUBSTATE.airport,own=HUBSTATE.own_ground_aircraft||[];
  own.forEach((pl,i)=>{
    const gate=hubGatePoints.length?hubGatePoints[i%hubGatePoints.length].coords:[a.lon,a.lat];
    const el=document.createElement('button');el.className='player-aircraft-marker';el.innerHTML=`<span class="plane-glyph">✈</span><small>${pl.tail}</small>`;
    el.addEventListener('click',()=>inspectGroundPlane(pl));
    const m=new maplibregl.Marker({element:el}).setLngLat(gate).addTo(hubMap);hubTrafficMarkers.push(m);
    if((pl.phase||'').includes('taxi'))animateAlongNetwork(m,1000+i,'plane',16);
    if(pl.ground_service&&pl.ground_service!=='taxi'){
      const icons={fuel:'⛽',cleaning:'🧹',catering:'▰',passenger:'🚌',pushback:'↔'},ve=document.createElement('div');ve.className='ground-service-marker';ve.textContent=icons[pl.ground_service]||'▰';
      const vm=new maplibregl.Marker({element:ve}).setLngLat(groundPath('vehicle',i)?.coords?.[0]||gate).addTo(hubMap);hubTrafficMarkers.push(vm);animateAlongNetwork(vm,2000+i,'vehicle',12)
    }
  });
  let live={states:[],source:'indisponible'};
  try{live=await api('/api/live-traffic?ident='+encodeURIComponent(activeHubIdent))}catch(e){console.warn(e)}
  const real=(live.states||[]).filter(x=>x.on_ground||x.phase==='terminal-area').slice(0,55);
  real.forEach(st=>{
    const el=document.createElement('button');el.className=`real-aircraft-marker ${st.on_ground?'surface':'terminal'}`;
    el.innerHTML=`<span class="plane-glyph" style="transform:rotate(${st.heading||0}deg)">✈</span><small>${st.callsign||st.flight||st.reg||st.type||'LIVE'}</small>`;
    el.title=`${st.callsign||st.flight||'Trafic réel'} · ${live.source}`;
    el.addEventListener('click',()=>{ $('#hubInspectorContent').innerHTML=`<span class="inspector-tag">${live.source}</span><h2 class="inspector-title">${st.callsign||st.flight||'Vol réel'}</h2><div class="stat-row"><span>Appareil</span><b>${st.type||'—'} ${st.reg||''}</b></div><div class="stat-row"><span>Route</span><b>${st.origin||'—'} → ${st.destination||'—'}</b></div><div class="stat-row"><span>Phase</span><b>${st.on_ground?'Au sol':'Zone terminale'}</b></div><div class="stat-row"><span>Vitesse</span><b>${Math.round(st.velocity_kts||0)} kt</b></div><div class="stat-row"><span>Distance terrain</span><b>${st.distance_km!=null?st.distance_km+' km':'—'}</b></div>`;$('#hubInspector').classList.add('open')});
    const m=new maplibregl.Marker({element:el}).setLngLat([st.lon,st.lat]).addTo(hubMap);hubTrafficMarkers.push(m)
  });
  const baseMeta=`${HUBSTATE.airport.municipality||''} · Hub niv. ${HUBSTATE.hub.level} · ${HUBSTATE.airport.runway_count} piste(s)`;
  $('#hubMeta').textContent=`${baseMeta} · trafic ${live.source} : ${live.ground_count??real.filter(x=>x.on_ground).length} au sol / ${live.nearby_count??(live.states||[]).length} proches`;
  if($('#hubTrafficStatus')){const fr=String(live.source||'').toLowerCase().includes('flightradar');const bad=live.source==='unavailable'||live.source==='indisponible';$('#hubTrafficStatus').textContent=`${fr?'FR24':live.source||'Trafic'} · ${live.ground_count??real.filter(x=>x.on_ground).length} sol · ${live.nearby_count??(live.states||[]).length} proches`;$('#hubTrafficStatus').className='live-status '+(bad?'bad':fr?'ok':'warn')}
}

// Real traffic in the current globe viewport, with FR24 official API support on the backend when licensed.
async function refreshWorldRealTraffic(){if(!worldMap||!worldMap.loaded()||worldMap.getZoom()<2.15)return;const now=Date.now();if(now-lastWorldTrafficAt<30000)return;lastWorldTrafficAt=now;const b=worldMap.getBounds();try{const d=await api(`/api/live-traffic/box?lamin=${b.getSouth()}&lomin=${b.getWest()}&lamax=${b.getNorth()}&lomax=${b.getEast()}&limit=140`);worldRealMarkers.forEach(m=>m.remove());worldRealMarkers=[];(d.states||[]).filter(x=>!x.on_ground).slice(0,140).forEach(x=>{const el=document.createElement('button');el.className='world-real-marker';el.textContent='✈';el.style.transform=`rotate(${x.heading||0}deg)`;el.title=`${x.callsign||x.flight||'Vol'} · ${x.type||''} · ${d.source}`;el.addEventListener('click',()=>{$('#worldInspectorContent').innerHTML=`<span class="inspector-tag">${d.source}</span><h2 class="inspector-title">${x.callsign||x.flight||'Vol réel'}</h2><div class="stat-row"><span>Appareil</span><b>${x.type||'—'} ${x.reg||''}</b></div><div class="stat-row"><span>Route</span><b>${x.origin||'—'} → ${x.destination||'—'}</b></div><div class="stat-row"><span>Altitude</span><b>${fmt(x.altitude_ft||0)} ft</b></div><div class="stat-row"><span>Vitesse</span><b>${Math.round(x.velocity_kts||0)} kt</b></div>`;$('#worldInspector').classList.add('open')});worldRealMarkers.push(new maplibregl.Marker({element:el}).setLngLat([x.lon,x.lat]).addTo(worldMap))})}catch(e){console.warn(e)}}
function subsolarVector(){const now=new Date(),doy=Math.floor((now-Date.UTC(now.getUTCFullYear(),0,0))/86400000),decl=23.44*Math.sin((2*Math.PI/365)*(doy-81))*Math.PI/180,utc=now.getUTCHours()+now.getUTCMinutes()/60,lon=(12-utc)*15*Math.PI/180;return[Math.cos(decl)*Math.cos(lon),Math.cos(decl)*Math.sin(lon),Math.sin(decl)]}
function nightGrid(){const s=subsolarVector(),features=[];for(let lat=-80;lat<80;lat+=10)for(let lon=-180;lon<180;lon+=10){const p=(lat+5)*Math.PI/180,l=(lon+5)*Math.PI/180,v=[Math.cos(p)*Math.cos(l),Math.cos(p)*Math.sin(l),Math.sin(p)];if(v[0]*s[0]+v[1]*s[1]+v[2]*s[2]<0)features.push({type:'Feature',geometry:{type:'Polygon',coordinates:[[[lon,lat],[lon+10,lat],[lon+10,lat+10],[lon,lat+10],[lon,lat]]]},properties:{}})}return{type:'FeatureCollection',features}}
function ensureNightLayer(){if(!worldMap||!worldMap.loaded())return;const data=nightGrid();if(worldMap.getSource('night-side'))worldMap.getSource('night-side').setData(data);else{worldMap.addSource('night-side',{type:'geojson',data});worldMap.addLayer({id:'night-side',type:'fill',source:'night-side',paint:{'fill-color':'#020711','fill-opacity':.54}})}}
function initWorldMap(){worldMap=new maplibregl.Map({container:'worldMap',style:{...SAT_STYLE,projection:{type:'globe'}},center:[10,25],zoom:1.35,pitch:18,bearing:0,maxPitch:80});worldMap.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');worldMap.on('load',async()=>{worldMap.setProjection({type:'globe'});await loadMajorAirports();await addWeather();ensureNightLayer();syncWorldRoutes();syncWorldAircraft();refreshWorldRealTraffic()});worldMap.on('moveend',refreshWorldRealTraffic);worldMap.on('zoomend',refreshWorldRealTraffic);worldMap.on('click','major-airports',e=>inspectWorldAirport(e.features[0].properties));worldMap.on('click','owned-hubs',e=>inspectWorldAirport(e.features[0].properties));setInterval(()=>{ensureNightLayer();refreshWorldRealTraffic()},45000)}

// Stable observation cockpit: sky + horizon + forward satellite landscape + live weather.
function ensureCockpitMap(){if(cockpitMap)return;cockpitMap=new maplibregl.Map({container:'cockpitMap',style:SAT_STYLE,center:[2.5,49],zoom:9,pitch:84,bearing:0,interactive:false,attributionControl:true,maxPitch:85})}
function localLight(lon){const d=new Date(),h=(d.getUTCHours()+d.getUTCMinutes()/60+lon/15+24)%24;if(h<5.5||h>20.5)return'night';if(h<7||h>19)return'dawn';return'day'}
let lastCockpitWeather={cloud:20,prec:0,code:0};
window.openCockpit=id=>{selectedAircraft=id;ensureCockpitMap();$('#cockpitModal').classList.add('open');setTimeout(()=>cockpitMap?.resize(),80);updateCockpit(true)};
async function updateCockpit(force=false){if(!selectedAircraft||!STATE)return;const a=STATE.aircraft.find(x=>x.id===selectedAircraft);if(!a)return;const f=a.flight;$('#cpAircraft').textContent=`${a.tail} · ${a.spec.name}`;if(!f){$('#cpFlight').textContent='AU SOL';$('#cpStatus').textContent='Disponible';return}$('#cpFlight').textContent=`${f.from} → ${f.to}`;$('#cpAlt').textContent=fmt(f.altitude_ft)+' ft';$('#cpSpeed').textContent=f.speed_kts+' kt';$('#cpHeading').textContent=Math.round(f.heading)+'°';$('#cpFuel').textContent=f.fuel_percent+'%';$('#cpStatus').textContent=f.status;const light=localLight(f.lon),sky=$('#cockpitSky');sky.classList.toggle('night',light==='night');$('#cockpitModal').classList.toggle('night',light==='night');if(light==='dawn'&&!sky.classList.contains('night'))sky.style.background='linear-gradient(#173552,#d97b68 66%,#f2c28f 100%)';else sky.style.background='';if(cockpitMap&&cockpitMap.loaded()){const z=f.airborne?Math.max(7.1,10.7-f.altitude_ft/13000):15.5;cockpitMap.easeTo({center:[f.lon,f.lat],bearing:f.heading,pitch:f.airborne?84:67,zoom:z,duration:force?0:2600,easing:t=>t})}const now=Date.now();if(force||now-lastWeatherAt>90000){lastWeatherAt=now;try{const w=await api(`/api/weather/current?lat=${f.lat}&lon=${f.lon}`),c=w.current||{};lastCockpitWeather={cloud:Number(c.cloud_cover||0),prec:Number(c.precipitation||0),code:Number(c.weather_code||0)};$('#cpWeather').textContent=w.ok?`${Math.round(lastCockpitWeather.cloud)}% nuages · ${Math.round(c.wind_speed_10m||0)} kt`:'Indispo'}catch{}}const {cloud,prec,code}=lastCockpitWeather;$('#cockpitClouds').style.opacity=Math.min(.9,.04+cloud/112);$('#rainStreaks').style.opacity=prec>.15?Math.min(.7,.15+prec/6):0;$('#cockpitHaze').style.opacity=.18+cloud/180;stormy=code>=95||prec>=3;if(stormy&&Math.random()>.78)triggerStorm()}

