async function renderManagement(){const root=$('#managementContent');if(!root)return;root.innerHTML='<div class="empty-state"><b>Chargement…</b></div>';try{if(managementTab==='staff')return renderStaff(root);if(managementTab==='marketing')return renderMarketing(root);if(managementTab==='finance')return renderFinance(root);if(managementTab==='partners')return renderPartners(root);if(managementTab==='hotels')return renderHotels(root)}catch(e){root.innerHTML=`<div class="empty-state"><b>Erreur</b><span>${e.message}</span></div>`}}
async function renderStaff(root){const [staff,cands]=await Promise.all([api('/api/staff'),api('/api/staff/candidates')]);root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Équipe (${staff.items.length})</h2><p class="muted">Pilotes, PNC, maintenance, sol et fonctions siège. Si tes pools sont insuffisants, OPS fait appel à du personnel contractuel plus coûteux.</p><div>${staff.items.length?staff.items.map(e=>`<div class="staff-card"><div><b>${e.name}</b><span>${e.role_label}${e.qualification?' · '+e.qualification:''} · ${money(e.salary_monthly)}/mois · qualité ${e.quality}%</span></div><button class="mini-btn danger-btn" data-fire="${e.id}">Licencier</button></div>`).join(''):'<div class="empty-state"><span>Aucun salarié recruté.</span></div>'}</div></section><section class="panel"><h2>Marché du recrutement</h2><div id="candidateList">${cands.items.slice(0,24).map(c=>`<div class="staff-card"><div><b>${c.name}</b><span>${c.role_label}${c.qualification?' · '+c.qualification:''} · ${money(c.salary_monthly)}/mois · qualité ${c.quality}%</span></div><button class="mini-btn" data-hire="${c.id}">Recruter · ${money(c.hiring_fee)}</button></div>`).join('')}</div></section></div>`;root.querySelectorAll('[data-fire]').forEach(b=>b.addEventListener('click',async()=>{await api('/api/staff/'+b.dataset.fire,{method:'DELETE'});toast('Employé libéré');renderStaff(root);loadState()}));root.querySelectorAll('[data-hire]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/staff/hire',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidate_id:b.dataset.hire,home_hub:activeHubIdent||''})});toast('Recrutement effectué');await loadState();renderStaff(root)}catch(e){toast(e.message)}}))}
async function renderMarketing(root){const d=await api('/api/marketing');root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Campagnes</h2><div class="estimate-grid"><div><small>Boost demande</small><b>+${Math.round(d.boost*100)}%</b></div><div><small>Directeur marketing</small><b>${d.has_director?'Oui':'Non'}</b></div></div>${d.campaigns.map(c=>`<div class="list-row"><div><b>${c.name}</b><small>${money(c.spend)} · ${c.active?'ACTIVE':'Terminée'}</small></div><b>+${Math.round(c.impact*100)}%</b></div>`).join('')||'<div class="empty-state"><span>Aucune campagne.</span></div>'}</section><section class="panel"><h2>Lancer une campagne</h2><label>Type<select id="mtype"><option value="brand">Notoriété mondiale</option><option value="digital">Acquisition digitale</option><option value="route">Lancement de ligne</option><option value="premium">Premium</option><option value="loyalty">Fidélité</option></select></label><label>Budget (€)<input type="number" id="mspend" value="1000000" min="100000"></label><label>Durée<input type="number" id="mdays" value="14" min="3" max="60"></label><button class="primary" id="startCampaign">Lancer</button></section></div>`;$('#startCampaign').addEventListener('click',async()=>{try{await api('/api/marketing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaign_type:$('#mtype').value,spend:Number($('#mspend').value),duration_days:Number($('#mdays').value)})});toast('Campagne lancée');await loadState();renderMarketing(root)}catch(e){toast(e.message)}})}
async function renderFinance(root){const d=await api('/api/finance');root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Finance</h2><div class="estimate-grid"><div><small>Trésorerie</small><b>${money(d.cash)}</b></div><div><small>Masse salariale</small><b>${money(d.monthly_payroll)}/mois</b></div><div><small>Dette</small><b>${money(d.loans.reduce((s,x)=>s+x.outstanding,0))}</b></div><div><small>Dernier vol</small><b>${d.flights[0]?money(d.flights[0].profit):'—'}</b></div></div><h3>Résultat par vol</h3><div class="table-scroll"><table class="finance-table"><thead><tr><th>Vol</th><th>Pax</th><th>Recettes</th><th>Coûts</th><th>Profit</th></tr></thead><tbody>${d.flights.slice(0,30).map(f=>`<tr><td>${f.tail} · ${f.origin}→${f.destination}</td><td>${f.passengers} · ${Math.round(f.load_factor*100)}%</td><td>${money(f.ticket_revenue+f.ancillary_revenue)}</td><td>${money(f.operating_cost)}</td><td class="${f.profit>=0?'profit-pos':'profit-neg'}">${money(f.profit)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Banque</h2><label>Montant<input id="loanAmount" type="number" value="25000000" min="1000000"></label><label>Durée<select id="loanTerm"><option>12</option><option>24</option><option selected>36</option><option>48</option><option>60</option></select></label><button class="primary" id="takeLoan">Demander l’emprunt</button><h3>Emprunts en cours</h3>${d.loans.map(l=>`<div class="manage-card"><b>${money(l.outstanding)}</b><p>${(l.apr*100).toFixed(2)}% · ${l.term_months} mois</p><button class="mini-btn" data-repay="${l.id}" data-out="${l.outstanding}">Rembourser 10%</button></div>`).join('')||'<p class="muted">Aucun emprunt.</p>'}</section></div>`;$('#takeLoan').addEventListener('click',async()=>{try{await api('/api/finance/loan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number($('#loanAmount').value),term_months:Number($('#loanTerm').value)})});toast('Emprunt débloqué');await loadState();renderFinance(root)}catch(e){toast(e.message)}});root.querySelectorAll('[data-repay]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/finance/loan/repay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({loan_id:Number(b.dataset.repay),amount:Number(b.dataset.out)*.1})});toast('Remboursement effectué');await loadState();renderFinance(root)}catch(e){toast(e.message)}}))}
async function renderPartners(root){const d=await api('/api/partners');root.innerHTML=`<div class="management-grid three">${d.offers.map(o=>`<article class="manage-card"><h3>${o.name}</h3><small>${o.type}</small><p>Bonus revenus +${(o.revenue_bonus*100).toFixed(1)}% · réputation +${o.reputation_bonus}</p><button class="${o.owned?'secondary':'primary'}" data-partner="${o.id}" ${o.owned?'disabled':''}>${o.owned?'Partenaire actif':'Signer · '+money(o.fee)}</button></article>`).join('')}</div>`;root.querySelectorAll('[data-partner]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/partners',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offer_id:b.dataset.partner})});toast('Partenariat signé');await loadState();renderPartners(root)}catch(e){toast(e.message)}}))}
async function renderHotels(root){const d=await api('/api/hotels');root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Mes hôtels</h2>${d.items.map(h=>`<div class="manage-card"><h3>${h.name}</h3><p>${h.airport_ident} · ${h.stars}★ · ${h.rooms} chambres · niv. ${h.level}/10</p><button class="mini-btn" data-hotelup="${h.id}">Agrandir</button></div>`).join('')||'<p class="muted">Aucun hôtel construit.</p>'}</section><section class="panel"><h2>Construire un hôtel</h2><label>Hub<select id="hotelHub">${STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('')}</select></label><label>Nom<input id="hotelName" value="${STATE.profile.logo_text} Hotel"></label><label>Étoiles<select id="hotelStars"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Chambres<input id="hotelRooms" type="number" value="120" min="60" max="900"></label><button class="primary" id="buildHotel">Construire</button></section></div>`;$('#buildHotel').addEventListener('click',async()=>{try{await api('/api/hotels',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({airport_ident:$('#hotelHub').value,name:$('#hotelName').value,stars:Number($('#hotelStars').value),rooms:Number($('#hotelRooms').value)})});toast('Hôtel construit');await loadState();renderHotels(root)}catch(e){toast(e.message)}});root.querySelectorAll('[data-hotelup]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/hotels/upgrade',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hotel_id:Number(b.dataset.hotelup)})});toast('Hôtel agrandi');await loadState();renderHotels(root)}catch(e){toast(e.message)}}))}

function loadState(){return api('/api/state').then(d=>{STATE=d;renderHeader();renderHubSelector();if(typeof renderOwnedHubs==='function')renderOwnedHubs();renderFleet();renderRoutes();syncWorldRoutes();syncWorldAircraft();syncIdentity();updateCockpit();if(document.querySelector('[data-view="management"]')?.classList.contains('active'))renderManagement()}).catch(e=>{if(e.message.includes('connect'))location.href='/login';else toast(e.message)})}

function initWorldAITraffic(){ aiWorldMarkers.forEach(m=>m.remove()); aiWorldMarkers=[]; aiWorldFlights=[]; }


// ---------- v0.6 PREMIUM REALISM OVERRIDES ----------
function nav(name){
  $$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));
  $$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));
  $('#moreMenu')?.classList.remove('open');$('#moreBackdrop')?.classList.remove('open');
  if(name==='hub'){
    if(!hubMap)initHubMap();
    setTimeout(()=>{hubMap?.resize();if(activeHubIdent&&hubMap?.loaded())loadHub(activeHubIdent)},80);
  }
  if(name==='world'){
    if(!worldMap)initWorldMap();
    setTimeout(()=>{worldMap?.resize();syncWorldRoutes();syncWorldAircraft()},80);
  }
  if(name==='management')setTimeout(renderManagement,0);if(name==='specialops')setTimeout(renderSpecialOps,0);if(name==='career')setTimeout(renderCareer,0);
  window.scrollTo(0,0);
}

function renderHeader(){
  if(!STATE)return;
  $('#companyName').textContent=(STATE.profile.logo_text||STATE.user.company_name).toUpperCase();
  $('#cash').textContent=money(STATE.user.cash);$('#rep').textContent=STATE.user.reputation+'%';$('#fleetCount').textContent=STATE.aircraft.length;
  $('#playerLevel').textContent=STATE.progression?.level||1;$('#globalSat').textContent=(STATE.company?.satisfaction||0)+'%';
  const h=STATE.hubs.find(x=>x.is_primary)||STATE.hubs[0];$('#activeHubLabel').textContent=h?h.airport.code:'—';
  document.documentElement.style.setProperty('--company-primary',STATE.profile.primary_color);document.documentElement.style.setProperty('--company-accent',STATE.profile.accent_color);
}

function satClass(v){return v>=85?'good':v>=70?'warn':'bad'}
function renderHome(){
  if(!STATE)return;
  const pr=STATE.progression||{},h=STATE.hubs.find(x=>x.is_primary)||STATE.hubs[0],company=STATE.company||{};
  $('#homeUsername').textContent=STATE.user.username||'Commandant';$('#homeLevel').textContent=pr.level||1;$('#homeEraLabel').textContent=pr.era||'Fondateur';
  $('#homeEra').textContent=`${pr.era||'Fondateur'} · ${STATE.routes.length} ligne(s), ${STATE.hubs.length} hub(s). Les équipages sont affectés automatiquement selon les qualifications et le repos.`;
  $('#homeXp').textContent=`${fmt(pr.xp_current||0)} / ${fmt(pr.xp_next||0)} XP`;$('#homeXpBar').style.width=(pr.progress_pct||0)+'%';
  $('#homeProfit').textContent=money(company.today_profit||0);$('#homeFlights').textContent=`${company.today_flights||0} rotation(s)`;$('#homePax').textContent=fmt(company.today_passengers||0);
  $('#homeSat').textContent=(company.satisfaction||0)+'%';$('#homeSatLabel').textContent=(company.satisfaction||0)>=90?'Excellent':(company.satisfaction||0)>=80?'Très bon':'À développer';$('#homeFleet').textContent=STATE.aircraft.length;
  if(h){
    const sat=h.satisfaction||{score:0,label:'—'},r=h.reality||{};$('#homeHubTitle').textContent=`${h.airport.code} · ${h.airport.name}`;
    $('#homeHubBody').innerHTML=`<div class="hub-summary-photo"><div class="hub-code">${h.airport.code}</div></div><div class="hub-summary-data"><div><small>PROFIL</small><b>${r.character||'Aéroport'}</b></div><div><small>NIVEAU HUB</small><b>${h.level}</b></div><div class="sat-bar"><small>SATISFACTION</small><b>${sat.score}% · ${sat.label}</b><div class="sat-meter"><i style="width:${sat.score}%"></i></div></div><div><small>INFRASTRUCTURES ACQUISES</small><b>${h.asset_count}</b></div><div><small>ACCÈS</small><b>${(r.access||[]).slice(0,2).join(' · ')||'—'}</b></div></div>`;
  }
  const qs=STATE.quests?.items||[];$('#homeQuests').innerHTML=qs.map(q=>{const pct=Math.min(100,q.value/q.target*100);return `<div class="quest-item"><div><b>${q.label}</b><small>${fmt(q.value)} / ${fmt(q.target)} · ${money(q.cash_reward)} + ${q.xp_reward} XP + ${q.token_reward||0} ◉</small><div class="quest-progress"><i style="width:${pct}%"></i></div></div><button data-claimquest="${q.code}" ${!q.complete||q.claimed?'disabled':''}>${q.claimed?'Récupéré':q.complete?'Récupérer':'En cours'}</button></div>`}).join('')||'<div class="empty-state"><span>Aucun objectif aujourd’hui.</span></div>';
  $('#homeQuests').querySelectorAll('[data-claimquest]').forEach(b=>b.addEventListener('click',async()=>{try{const d=await api('/api/quests/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quest_code:b.dataset.claimquest})});toast(`Récompense : ${money(d.cash_reward)} + ${d.xp_reward} XP + ${d.token_reward||0} tokens`);await loadState()}catch(e){toast(e.message)}}));
  const crewRoutes=STATE.routes.slice(0,5);$('#homeCrew').innerHTML=crewRoutes.length?crewRoutes.map(r=>{const c=r.crew||{},cls=(c.coverage_percent||0)>=100?'risk-good':(c.coverage_percent||0)>=60?'risk-warn':'risk-bad';return `<div class="crew-route"><div><b>${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${c.reinforced?'Équipage renforcé long-courrier':'Équipage standard'} · affectation automatique</small></div><div class="${cls}"><b>${c.coverage_percent||0}%</b><small>${c.fatigue_risk||'—'}</small></div></div>`}).join(''):'<div class="empty-state"><span>Ouvre une ligne pour calculer la couverture équipage.</span></div>';
  const live=STATE.routes.filter(r=>r.flight).slice(0,5);$('#homeFlightsList').innerHTML=live.length?live.map(r=>`<div class="home-flight"><div><b>${r.tail} · ${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${r.flight.status}</small></div><button class="mini-btn" onclick="openCockpit(${r.aircraft_id})">Observer</button></div>`).join(''):'<div class="empty-state"><span>Aucun vol actif.</span></div>';
}

async function loadHub(ident){
  if(!hubMap||!hubMap.loaded())return;
  try{
    HUBSTATE=await api('/api/hub/'+encodeURIComponent(ident));
    $('#hubTitle').textContent=`${HUBSTATE.airport.code} · ${HUBSTATE.airport.name}`;
    $('#hubMeta').textContent=`${HUBSTATE.airport.municipality||''} · Hub niv. ${HUBSTATE.hub.level} · ${HUBSTATE.airport.runway_count} piste(s)`;
    $('#hubSatMini').textContent=(HUBSTATE.hub.satisfaction?.score||0)+'%';$('#hubRealityMini').textContent=HUBSTATE.reality?.character||'Aéroport';
    drawHubRunways();await loadHubSurfaceNetwork();drawHubUpgrades();focusHub();await refreshHubTraffic();
  }catch(e){toast(e.message)}
}

function catIcon(cat){return {'Airside':'✈','Terminal':'▤','Sécurité':'◈','Commercial':'▣','Premium':'◇','Technique':'⚙','Cargo':'□','Infrastructure':'⌂'}[cat]||'•'}
function drawHubUpgrades(){
  clearMarkers(hubUpgradeMarkers);if(!HUBSTATE)return;const visible=$('#toggleUpgrades')?.classList.contains('active');
  HUBSTATE.nodes.forEach(n=>{const el=document.createElement('button');el.className='hub-upgrade-marker '+n.state;el.textContent=`${catIcon(n.cat)} ${n.state==='locked'?'🔒':n.level||'+'}`;el.title=`${n.name} · ${n.state==='active'?'niveau '+n.level:n.state==='available'?'disponible':'verrouillé'}`;el.style.display=visible?'flex':'none';el.addEventListener('click',()=>inspectUpgrade(n));hubUpgradeMarkers.push(new maplibregl.Marker({element:el}).setLngLat([n.lon,n.lat]).addTo(hubMap))});
}

async function loadHubSurfaceNetwork(){
  if(!hubMap||!HUBSTATE)return;
  ['hub-terminals','hub-aprons','hub-taxiways','hub-osm-runways','hub-gates'].forEach(id=>hubMap.getLayer(id)&&hubMap.removeLayer(id));if(hubMap.getSource('hub-surface'))hubMap.removeSource('hub-surface');
  hubSurfaceLines=[];hubGatePoints=[];hubSurfaceFeatures=[];clearMarkers(hubAssetMarkers);
  try{
    const geo=await api('/api/hub/'+encodeURIComponent(activeHubIdent)+'/surface-network');hubSurfaceSource=geo.source||'surface';hubSurfaceFeatures=geo.features||[];hubMap.addSource('hub-surface',{type:'geojson',data:geo});
    hubMap.addLayer({id:'hub-terminals',type:'fill',source:'hub-surface',filter:['==',['get','kind'],'terminal'],paint:{'fill-color':'#e7edf1','fill-opacity':.50,'fill-outline-color':'#ffffff'}});
    hubMap.addLayer({id:'hub-aprons',type:'fill',source:'hub-surface',filter:['==',['get','kind'],'apron'],paint:{'fill-color':'#bdd0dc','fill-opacity':.12,'fill-outline-color':'#dfeaf0'}});
    hubMap.addLayer({id:'hub-taxiways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'taxiway'],paint:{'line-color':'#e4b84f','line-width':['interpolate',['linear'],['zoom'],11,.6,17,2.7],'line-opacity':.68}});
    hubMap.addLayer({id:'hub-osm-runways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'runway'],paint:{'line-color':'#f5f7f8','line-width':['interpolate',['linear'],['zoom'],11,1,17,5],'line-opacity':.72}});
    hubMap.addLayer({id:'hub-gates',type:'circle',source:'hub-surface',filter:['in',['get','kind'],['literal',['gate','parking_position']]],paint:{'circle-radius':['interpolate',['linear'],['zoom'],12,1.2,17,3.2],'circle-color':'#ffffff','circle-opacity':.58,'circle-stroke-color':'#526777','circle-stroke-width':.7}});
    hubSurfaceFeatures.forEach(f=>{const k=f.properties?.kind;if(f.geometry?.type==='LineString'&&(k==='taxiway'||k==='runway'))hubSurfaceLines.push({kind:k,coords:f.geometry.coordinates,feature:f});if(f.geometry?.type==='Point'&&(k==='gate'||k==='parking_position'))hubGatePoints.push({coords:f.geometry.coordinates,feature:f})});drawHubAssets();
    $('#hubMeta').textContent+=` · réseau sol ${hubSurfaceSource.includes('OpenStreetMap')?'OSM réel':'pistes connues'}`;
  }catch(e){console.warn(e)}
}

function drawHubAssets(){
  clearMarkers(hubAssetMarkers);if(!HUBSTATE)return;const candidates=[];const lim=HUBSTATE.airport.type==='large_airport'?120:HUBSTATE.airport.type==='medium_airport'?80:45;hubGatePoints.slice(0,lim).forEach(x=>candidates.push(x.feature));hubSurfaceFeatures.filter(f=>f.properties?.kind==='runway'&&f.geometry?.type==='LineString').forEach(f=>candidates.push(f));
  candidates.forEach((f,i)=>{const kind=f.properties?.kind,key=f.properties?.asset_key||`${kind}:${i}`,name=f.properties?.name||(`${kind==='gate'?'Porte':kind==='parking_position'?'Parking avion':'Piste'} ${i+1}`);let pt=f.geometry.type==='Point'?f.geometry.coordinates:pointOnLine(f.geometry.coordinates,.5);if(!pt)return;const owned=assetOwned(key),el=document.createElement('button');el.className=`hub-asset-marker ${owned?'owned':'locked'} ${kind==='runway'?'runway':''}`;el.textContent=owned?'✓':(kind==='gate'?'G':kind==='parking_position'?'P':'RWY');el.title=`${owned?'Acquis':'Verrouillé'} · ${name}`;el.addEventListener('click',()=>inspectHubAsset({key,kind,name,pt,owned}));hubAssetMarkers.push(new maplibregl.Marker({element:el}).setLngLat(pt).addTo(hubMap))});
}

async function renderStaff(root){
  const [staff,cands]=await Promise.all([api('/api/staff'),api('/api/staff/candidates')]);
  const crewLines=(STATE.routes||[]).map(r=>{const c=r.crew||{};return `<div class="crew-route"><div><b>${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${c.qualification||'Qualification'} · ${c.reinforced?'4 pilotes en service (long-courrier)':'2 pilotes en service'} · OPS automatique</small></div><div class="${(c.coverage_percent||0)>=100?'risk-good':(c.coverage_percent||0)>=60?'risk-warn':'risk-bad'}"><b>${c.coverage_percent||0}%</b><small>${c.pilots_available||0}/${c.pilots_recommended||0} pilotes recommandés</small></div></div>`}).join('');
  root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Équipages automatisés</h2><p class="muted">Tu recrutes les pilotes et PNC. OPS les affecte ensuite automatiquement aux rotations, gère les renforts long-courriers et mesure le risque fatigue. Avec 2 pilotes pour un avion la couverture est fragile ; avec 4 pilotes sur un appareil court/moyen-courrier, les rotations de repos deviennent beaucoup plus confortables.</p>${crewLines||'<div class="empty-state"><span>Crée une ligne pour voir les besoins d’équipage.</span></div>'}<h3>Personnel recruté (${staff.items.length})</h3><div>${staff.items.length?staff.items.map(e=>`<div class="staff-card"><div><b>${e.name}</b><span>${e.role_label}${e.qualification?' · '+e.qualification:''} · base ${e.home_hub||'mobile'} · ${money(e.salary_monthly)}/mois</span></div><button class="mini-btn danger-btn" data-fire="${e.id}">Licencier</button></div>`).join(''):'<div class="empty-state"><span>Aucun salarié recruté.</span></div>'}</div></section><section class="panel"><h2>Recrutement</h2><p class="muted">Le personnel recruté est basé sur le hub actif puis utilisé automatiquement par le moteur OPS.</p><div id="candidateList">${cands.items.filter(c=>['pilot','copilot','cabin_crew','mechanic','ground_agent'].includes(c.role)).slice(0,24).map(c=>`<div class="staff-card"><div><b>${c.name}</b><span>${c.role_label}${c.qualification?' · '+c.qualification:''} · qualité ${c.quality}% · ${money(c.salary_monthly)}/mois</span></div><button class="mini-btn" data-hire="${c.id}">Recruter · ${money(c.hiring_fee)}</button></div>`).join('')}</div></section></div>`;
  root.querySelectorAll('[data-fire]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/staff/'+b.dataset.fire,{method:'DELETE'});toast('Employé libéré');await loadState();renderStaff(root)}catch(e){toast(e.message)}}));
  root.querySelectorAll('[data-hire]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/staff/hire',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidate_id:b.dataset.hire,home_hub:activeHubIdent||(STATE.hubs.find(h=>h.is_primary)||STATE.hubs[0])?.ident||''})});toast('Recrutement effectué · affectation automatique active');await loadState();renderStaff(root)}catch(e){toast(e.message)}}));
}

async function renderFinance(root){
  const [d,banks]=await Promise.all([api('/api/finance'),api('/api/banks?ident='+encodeURIComponent((STATE.hubs.find(h=>h.is_primary)||STATE.hubs[0])?.ident||''))]);
  const allLoans=[...(d.bank_loans||[]),...(d.loans||[])],debt=allLoans.reduce((s,x)=>s+x.outstanding,0);
  root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Finance</h2><div class="estimate-grid"><div><small>Trésorerie</small><b>${money(d.cash)}</b></div><div><small>Masse salariale</small><b>${money(d.monthly_payroll)}/mois</b></div><div><small>Dette</small><b>${money(debt)}</b></div><div><small>Dernier vol</small><b>${d.flights[0]?money(d.flights[0].profit):'—'}</b></div></div><h3>Résultat par vol</h3><div class="table-scroll"><table class="finance-table"><thead><tr><th>Vol</th><th>Pax</th><th>Recettes</th><th>Coûts</th><th>Profit</th></tr></thead><tbody>${d.flights.slice(0,30).map(f=>`<tr><td>${f.tail} · ${f.origin}→${f.destination}</td><td>${f.passengers} · ${Math.round(f.load_factor*100)}%</td><td>${money(f.ticket_revenue+f.ancillary_revenue)}</td><td>${money(f.operating_cost)}</td><td class="${f.profit>=0?'profit-pos':'profit-neg'}">${money(f.profit)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Banques · ${banks.hub||banks.country}</h2><p class="muted">Les offres changent selon le pays de ton hub principal et ton niveau joueur.</p><div class="bank-offers">${banks.offers.map((b,i)=>`<button class="bank-offer ${i===0?'selected':''}" data-bank="${b.id}" ${b.available?'':'disabled'}><b>${b.name}</b><span>à partir de ${(b.base_apr*100).toFixed(2)}% · plafond ${money(b.max_amount)}</span><small>${b.available?b.advantage:'Niveau '+b.min_level+' requis'}</small></button>`).join('')}</div><input type="hidden" id="selectedBank" value="${banks.offers.find(x=>x.available)?.id||''}"><label>Montant<input id="loanAmount" type="number" value="25000000" min="1000000"></label><label>Durée<select id="loanTerm"><option>12</option><option>24</option><option selected>36</option><option>60</option><option>84</option><option>120</option></select></label><button class="primary" id="takeBankLoan" ${banks.offers.some(x=>x.available)?'':'disabled'}>Demander le financement</button><h3>Emprunts en cours</h3>${allLoans.map(l=>`<div class="manage-card"><b>${l.bank_name||'Banque'}</b><p>${money(l.outstanding)} · ${(l.apr*100).toFixed(2)}% · ${l.term_months} mois</p>${l.legacy?'':`<button class="mini-btn" data-bankrepay="${l.id}" data-out="${l.outstanding}">Rembourser 10%</button>`}</div>`).join('')||'<p class="muted">Aucun emprunt.</p>'}</section></div>`;
  const offerBtns=root.querySelectorAll('[data-bank]');offerBtns.forEach(btn=>btn.addEventListener('click',()=>{offerBtns.forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');$('#selectedBank').value=btn.dataset.bank}));
  $('#takeBankLoan')?.addEventListener('click',async()=>{try{await api('/api/finance/bank-loan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number($('#loanAmount').value),term_months:Number($('#loanTerm').value),bank_id:$('#selectedBank').value})});toast('Financement accordé');await loadState();renderFinance(root)}catch(e){toast(e.message)}});
  root.querySelectorAll('[data-bankrepay]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/finance/bank-loan/'+b.dataset.bankrepay+'/repay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({loan_id:Number(b.dataset.bankrepay),amount:Number(b.dataset.out)*.1})});toast('Remboursement effectué');await loadState();renderFinance(root)}catch(e){toast(e.message)}}));
}

