  root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Partenaires hôteliers réels par marché</h2><p class="muted">Les marques proposées dépendent du pays et du profil réel du hub. Aucun grand hôtel n’apparaît automatiquement dans un petit aéroport.</p>${(d.partner_offers||[]).map(o=>`<div class="manage-card"><h3>${o.name} · ${o.airport_code}</h3><p>${o.character} · satisfaction ${o.hub_satisfaction}%</p><button class="${o.available?'primary':'secondary'}" data-hotelpartner="${o.key}" ${o.available?'':'disabled'}>${o.available?'Signer · '+money(o.partnership_fee):'Niveau '+o.min_level+' + satisfaction 65%'}</button></div>`).join('')||'<p class="muted">Aucune offre disponible.</p>'}</section><section class="panel"><h2>Immobilier hôtelier du groupe</h2>${d.items.map(h=>`<div class="manage-card"><h3>${h.name}</h3><p>${h.airport_ident} · ${h.stars}★ · ${h.rooms} chambres · niv. ${h.level}/10</p><button class="mini-btn" data-hotelup="${h.id}">Agrandir</button></div>`).join('')||'<p class="muted">Aucun hôtel détenu.</p>'}<hr><h3>Construire votre propre hôtel</h3><p class="muted">Déblocage tardif : niveau joueur 20 et satisfaction hub ≥ 70%.</p><label>Hub<select id="hotelHub" ${canBuild?'':'disabled'}>${STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('')}</select></label><label>Nom<input id="hotelName" value="${STATE.profile.logo_text} Hotel" ${canBuild?'':'disabled'}></label><label>Étoiles<select id="hotelStars" ${canBuild?'':'disabled'}><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Chambres<input id="hotelRooms" type="number" value="120" min="60" max="900" ${canBuild?'':'disabled'}></label><button class="primary" id="buildHotel" ${canBuild?'':'disabled'}>${canBuild?'Construire':'Niveau 20 requis'}</button></section></div>`;
  root.querySelectorAll('[data-hotelpartner]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/hotels/partner',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offer_key:b.dataset.hotelpartner})});toast('Partenariat hôtelier signé');await loadState();renderHotels(root)}catch(e){toast(e.message)}}));
  $('#buildHotel')?.addEventListener('click',async()=>{try{await api('/api/hotels',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({airport_ident:$('#hotelHub').value,name:$('#hotelName').value,stars:Number($('#hotelStars').value),rooms:Number($('#hotelRooms').value)})});toast('Hôtel construit');await loadState();renderHotels(root)}catch(e){toast(e.message)}});
