function loadState(){return api('/api/state').then(d=>{STATE=d;renderHeader();renderHome();renderHubSelector();if(typeof renderOwnedHubs==='function')renderOwnedHubs();renderFleet();renderRoutes();if(worldMap){syncWorldRoutes();syncWorldAircraft()}syncIdentity();updateCockpit();if(document.querySelector('[data-view="management"]')?.classList.contains('active'))renderManagement()}).catch(e=>{if(e.message.includes('connect'))location.href='/login';else toast(e.message)})}

$('#menuBtn')?.addEventListener('click',()=>{$('#moreMenu')?.classList.toggle('open');$('#moreBackdrop')?.classList.toggle('open')});
$('#closeMoreMenu')?.addEventListener('click',()=>{$('#moreMenu')?.classList.remove('open');$('#moreBackdrop')?.classList.remove('open')});
$('#moreBackdrop')?.addEventListener('click',()=>{$('#moreMenu')?.classList.remove('open');$('#moreBackdrop')?.classList.remove('open')});
$('#toggleRouteForm')?.addEventListener('click',()=>$('#routeForm')?.classList.add('mobile-open'));
$('#closeRouteForm')?.addEventListener('click',()=>$('#routeForm')?.classList.remove('mobile-open'));


