  root.innerHTML=`<section class="hr-premium-grid"><article class="panel hr-auto-card"><p class="eyebrow">AUTO-EMBAUCHE</p><h2>Capacité RH automatisée</h2><p class="muted">Tu fixes le budget. Le service RH complète les pools par hub ; OPS affecte ensuite les équipages automatiquement et respecte les besoins renforcés long-courrier.</p><label class="switch-row"><input id="hrAutoEnabled" type="checkbox" ${policy.enabled?'checked':''}> Activer l’auto-embauche</label><label>Budget mensuel RH<input id="hrBudget" type="number" min="100000" value="${Math.round(policy.monthly_budget)}"></label><div class="hr-budget-stats"><span>Paie actuelle <b>${money(policy.payroll)}/mois</b></span><span>Budget restant <b>${money(Math.max(0,policy.monthly_budget-policy.payroll))}</b></span></div><div class="form-two"><button class="primary" id="saveHRPolicy">Enregistrer</button><button class="secondary" id="balanceHRNow">Auto-équilibrer maintenant</button></div></article><article class="panel hr-target-card"><p class="eyebrow">CIBLES D’EFFECTIF PAR HUB</p><div class="table-scroll"><table class="finance-table"><thead><tr><th>Hub</th><th>Pilotes</th><th>PNC</th><th>Méc.</th><th>Sol</th><th>Statut</th></tr></thead><tbody>${targetRows||'<tr><td colspan="6">Aucun hub</td></tr>'}</tbody></table></div></article></section><section class="management-grid"><article class="panel"><h2>Couverture des rotations</h2>${crewLines||'<div class="empty-state"><span>Crée une ligne pour calculer les besoins.</span></div>'}<h3>Personnel recruté (${staff.items.length})</h3><div class="staff-roster">${staff.items.slice(0,60).map(e=>`<div class="staff-card"><div><b>${esc(e.name)}</b><span>${esc(e.role_label)}${e.qualification?' · '+esc(e.qualification):''} · ${esc(e.home_hub||'mobile')} · ${money(e.salary_monthly)}/mois</span></div><button class="mini-btn danger-btn" data-fire="${e.id}">Licencier</button></div>`).join('')||'<p class="muted">Aucun salarié.</p>'}</div></article><article class="panel"><h2>Marché du recrutement</h2><div id="candidateList">${cands.items.filter(c=>['pilot','copilot','cabin_crew','mechanic','ground_agent'].includes(c.role)).slice(0,28).map(c=>`<div class="staff-card"><div><b>${esc(c.name)}</b><span>${esc(c.role_label)}${c.qualification?' · '+esc(c.qualification):''} · qualité ${c.quality}%${c.discount_percent>0?` · bonus RH/alliance −${c.discount_percent}%`:''}</span></div><button class="mini-btn" data-hire="${c.id}">Recruter · ${money(c.hiring_fee)}</button></div>`).join('')}</div></article></section>`;
  $('#saveHRPolicy')?.addEventListener('click',async()=>{try{await api('/api/hr/policy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:$('#hrAutoEnabled').checked,monthly_budget:Number($('#hrBudget').value),target_buffer_percent:15})});toast('Politique RH enregistrée');renderStaff(root)}catch(e){toast(e.message)}});
