async function renderFinance(root){
  const [f,banks,ipo]=await Promise.all([api('/api/finance'),api('/api/banks?ident='+encodeURIComponent(activeHubIdent||'')),api('/api/ipo')]);const debt=[...(f.loans||[]),...(f.bank_loans||[])].reduce((s,x)=>s+Number(x.outstanding||0),0),recent=(f.transactions||[]).slice(0,16),reqs=Object.values(ipo.requirements||{});
  root.innerHTML=`<section class="finance-premium-head"><article class="panel finance-cash"><small>TRÉSORERIE</small><b>${money(f.cash)}</b><span>Masse salariale ${money(f.monthly_payroll)}/mois</span></article><article class="panel"><small>DETTE TOTALE</small><b>${money(debt)}</b><span>${(f.bank_loans||[]).length+(f.loans||[]).length} financement(s)</span></article><article class="panel"><small>${ipo.is_public?'CAPITALISATION SIMULÉE':'ÉVALUATION IPO'}</small><b>${money(ipo.valuation)}</b><span>${ipo.is_public?`${esc(ipo.ticker)} · confiance ${Math.round(ipo.market_confidence)}%`:'Préparation à l’introduction en Bourse'}</span></article></section>
  <section class="panel"><div class="finance-section-title"><div><p class="eyebrow">PARTENAIRES FINANCIERS</p><h2>Banques disponibles</h2></div><span class="muted">Offres adaptées au pays du hub principal</span></div><div class="bank-grid">${banks.offers.map(b=>{const logo=logoForBank(b.name);return `<article class="bank-card ${b.available?'':'locked'}">${logo?`<img src="${logo}" alt="${esc(b.name)}">`:`<h3>${esc(b.name)}</h3>`}<span class="bank-country">${esc(b.country||banks.country||'')}</span><div class="bank-stats"><div><small>TAUX DE BASE</small><b>${(b.base_apr*100).toFixed(2)}%</b></div><div><small>PLAFOND</small><b>${money(b.max_amount)}</b></div></div><p>${esc(b.advantage)}</p><button class="${b.available?'primary':'secondary'}" data-bank="${b.id}" data-bank-name="${esc(b.name)}" ${b.available?'':'disabled'}>${b.available?'Voir l’offre':'Niveau '+b.min_level+' requis'}</button></article>`}).join('')}</div></section>
  <section class="ipo-panel panel"><div class="ipo-copy"><p class="eyebrow">INTRODUCTION EN BOURSE</p><h2>${ipo.is_public?`${esc(ipo.ticker)} est cotée`:'Préparer SKYLINE aux marchés financiers'}</h2><p class="muted">L’IPO est une mécanique de fin de progression : elle ne remplace pas la rentabilité opérationnelle.</p><div class="ipo-requirements">${reqs.map(x=>`<div><span>${esc(x.label)}</span><i><em style="width:${Math.min(100,(Number(x.value)||0)/Math.max(1,Number(x.target)||1)*100)}%"></em></i><b class="${x.ok?'profit-pos':'profit-neg'}">${x.value}/${x.target}</b></div>`).join('')}</div></div><div class="ipo-action"><small>ÉVALUATION ESTIMÉE</small><b>${money(ipo.valuation)}</b>${ipo.is_public?`<span>Capital cédé ${ipo.equity_sold_percent}% · levé ${money(ipo.cash_raised)}</span><strong>${ipo.share_price.toFixed(2)} € / action simulée</strong>`:`<label>Capital à ouvrir<select id="ipoEquity"><option>10</option><option selected>15</option><option>20</option><option>25</option><option>30</option></select></label><label>Ticker<input id="ipoTicker" value="SKY" maxlength="6"></label><button class="gold-button" id="launchIPO" ${ipo.eligible?'':'disabled'}>${ipo.eligible?'Préparer l’introduction':'Prérequis non remplis'}</button>`}</div></section>
  <section class="management-grid"><article class="panel"><h2>Financements en cours</h2>${[...(f.bank_loans||[]),...(f.loans||[])].map(l=>`<div class="loan-row"><div><b>${esc(l.bank_name||'Financement')}</b><small>${(l.apr*100).toFixed(2)}% · ${l.term_months} mois</small></div><div><strong>${money(l.outstanding)}</strong>${l.legacy?'':`<button class="mini-btn" data-bank-repay="${l.id}" data-out="${l.outstanding}">Rembourser 10%</button>`}</div></div>`).join('')||'<p class="muted">Aucun financement en cours.</p>'}</article><article class="panel"><h2>Transactions récentes</h2><div class="transaction-list">${recent.map(t=>`<div><span>${esc(t.label)}</span><b class="${t.amount>=0?'profit-pos':'profit-neg'}">${money(t.amount)}</b></div>`).join('')||'<p class="muted">Aucune transaction.</p>'}</div></article></section>`;
  root.querySelectorAll('[data-bank]').forEach(btn=>btn.addEventListener('click',()=>{const offer=banks.offers.find(x=>x.id===btn.dataset.bank),amount=Math.min(50_000_000,offer?.max_amount||50_000_000);$('#pricingModalContent').innerHTML=`<p class="eyebrow">FINANCEMENT · ${esc(btn.dataset.bankName)}</p><h2>Choisir le montant et la durée</h2><label>Montant (€)<input id="bankLoanAmount" type="number" min="1000000" value="${amount}"></label><label>Durée<select id="bankLoanTerm"><option>12</option><option>24</option><option selected>36</option><option>48</option><option>60</option><option>84</option><option>120</option></select></label><button class="primary" id="confirmBankLoan">Obtenir le financement</button>`;$('#pricingModal').classList.add('open');$('#confirmBankLoan').addEventListener('click',async()=>{try{const out=await api('/api/finance/bank-loan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number($('#bankLoanAmount').value),term_months:Number($('#bankLoanTerm').value),bank_id:btn.dataset.bank})});toast(`${out.bank_name} · ${(out.apr*100).toFixed(2)}%`);$('#pricingModal').classList.remove('open');await loadState();renderFinance(root)}catch(e){toast(e.message)}})}));
  root.querySelectorAll('[data-bank-repay]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/finance/bank-loan/'+b.dataset.bankRepay+'/repay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({loan_id:Number(b.dataset.bankRepay),amount:Number(b.dataset.out)*.1})});toast('Remboursement effectué');await loadState();renderFinance(root)}catch(e){toast(e.message)}}));
  $('#launchIPO')?.addEventListener('click',async()=>{try{const out=await api('/api/ipo/launch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({equity_percent:Number($('#ipoEquity').value),ticker:$('#ipoTicker').value})});toast(`IPO ${out.ticker} réussie · ${money(out.cash_raised)} levés`);await loadState();renderFinance(root)}catch(e){toast(e.message)}})
}

