const TYPE_PHOTO_CACHE=new Map();
let TYPE_PHOTO_OBSERVER=null;
async function fetchTypePhoto(a){
  const code=String(a?.icao||'').toUpperCase();if(!code)return null;if(TYPE_PHOTO_CACHE.has(code))return TYPE_PHOTO_CACHE.get(code);
  const promise=api('/api/aircraft/type-photo?'+new URLSearchParams({icao:code,name:a?.name||'',manufacturer:a?.manufacturer||''}).toString()).then(d=>d?.found?d.photo:null).catch(()=>null);
  TYPE_PHOTO_CACHE.set(code,promise);const photo=await promise;TYPE_PHOTO_CACHE.set(code,photo);return photo;
}
function ensureTypePhotoObserver(){
  if(TYPE_PHOTO_OBSERVER||!('IntersectionObserver'in window))return;
  TYPE_PHOTO_OBSERVER=new IntersectionObserver(entries=>entries.forEach(async entry=>{if(!entry.isIntersecting)return;const el=entry.target;TYPE_PHOTO_OBSERVER.unobserve(el);const a={icao:el.dataset.icao,name:el.dataset.name,manufacturer:el.dataset.manufacturer};const p=await fetchTypePhoto(a);if(!p?.url||!el.isConnected)return;el.innerHTML=`<img loading="lazy" src="${esc(p.url)}" alt="${esc(a.manufacturer)} ${esc(a.name)}"><i class="verified-photo commons-chip">TYPE MATCH · ${esc(p.source||'Wikimedia')}</i>`;el.closest('.premium-aircraft-card')?.setAttribute('data-photo-source',p.source||'Wikimedia Commons')}),{rootMargin:'500px'});
}
function observeTypePhoto(el,a){if(!el||aircraftPhoto(a))return;el.dataset.icao=a.icao||'';el.dataset.name=a.name||'';el.dataset.manufacturer=a.manufacturer||'';ensureTypePhotoObserver();if(TYPE_PHOTO_OBSERVER)TYPE_PHOTO_OBSERVER.observe(el);else fetchTypePhoto(a).then(p=>{if(p?.url)el.innerHTML=`<img loading="lazy" src="${esc(p.url)}" alt="${esc(a.name)}"><i class="verified-photo commons-chip">TYPE MATCH</i>`})}

