// ---------- FR24 globe: global count, streamed snapshot, smooth movement ----------
let V13_WORLD_ROWS=new Map(),V13_WORLD_FETCHED_AT=0,V13_WORLD_SUMMARY=null,V13_ANIM_TIMER=null;
function ensureWorldOpsOverlay(){
  const view=document.querySelector('[data-view="world"]');if(!view||view.querySelector('.world-ops-kpis-v13'))return;
  const el=document.createElement('div');el.className='world-ops-kpis-v13';el.innerHTML=`<article><small>FR24 SUIVIS</small><b id="worldKpiTracked">—</b><span>positions mondiales</span></article><article><small>AFFICHÉS</small><b id="worldKpiLoaded">—</b><span>selon plan API</span></article><article><small>EN VOL</small><b id="worldKpiAirborne">—</b><span>trafic chargé</span></article><article><small>COUVERTURE</small><b id="worldKpiCoverage">—</b><span id="worldKpiMode">temps réel</span></article>`;view.appendChild(el)
}
function setWorldKpis(d){ensureWorldOpsOverlay();const tracked=Number(d.tracked_count||V13_WORLD_SUMMARY?.tracked_count||0),loaded=Number(d.total_count??d.loaded_count??0),air=Number(d.airborne_count||0),cov=d.coverage_pct??(tracked?Math.round(loaded/tracked*1000)/10:null);if($('#worldKpiTracked'))$('#worldKpiTracked').textContent=tracked?fmt(tracked):'—';if($('#worldKpiLoaded'))$('#worldKpiLoaded').textContent=fmt(loaded);if($('#worldKpiAirborne'))$('#worldKpiAirborne').textContent=fmt(air);if($('#worldKpiCoverage'))$('#worldKpiCoverage').textContent=cov!=null?`${cov}%`:'—';if($('#worldKpiMode'))$('#worldKpiMode').textContent=d.subscription_limited?'limite du plan FR24':'snapshot mondial'}
function movedCoordinate(x,elapsedSec){
  if(x.on_ground||!Number.isFinite(Number(x.velocity_kts))||Number(x.velocity_kts)<35)return [Number(x.lon),Number(x.lat)];const sec=Math.max(0,Math.min(150,elapsedSec)),nm=Number(x.velocity_kts)*sec/3600,rad=(Number(x.heading||0))*Math.PI/180,lat=Number(x.lat)+(nm*Math.cos(rad))/60,cos=Math.max(.12,Math.cos(Number(x.lat)*Math.PI/180)),lon=Number(x.lon)+(nm*Math.sin(rad))/(60*cos);if(lon>180)lon-=360;if(lon<-180)lon+=360;return [lon,Math.max(-89.5,Math.min(89.5,lat))]
}
function redrawInterpolatedTraffic(){if(!worldMap?.loaded()||!V13_WORLD_ROWS.size)return;const now=Date.now(),elapsed=(now-V13_WORLD_FETCHED_AT)/1000,features=[];V13_WORLD_ROWS.forEach((x,k)=>{const [lon,lat]=movedCoordinate(x,elapsed);features.push({type:'Feature',geometry:{type:'Point',coordinates:[lon,lat]},properties:{flight_key:k,heading:Number(x.heading||0),on_ground:Boolean(x.on_ground),phase:x.phase||'',airline:x.livery_airline||'',type:x.type||''}})});worldMap.getSource('world-real-traffic-v12')?.setData({type:'FeatureCollection',features})}
function addRealTrafficMarkers(d){
  ensureWorldTrafficLayers();LIVE_AIRCRAFT_BY_ID.clear();V13_WORLD_ROWS.clear();worldTrafficSource=d.source||'Flightradar24 API';const rows=(d.states||[]).filter(x=>Number.isFinite(Number(x.lat))&&Number.isFinite(Number(x.lon)));rows.forEach(x=>{const k=flightIdentityKey(x);LIVE_AIRCRAFT_BY_ID.set(k,x);V13_WORLD_ROWS.set(k,x)});V13_WORLD_FETCHED_AT=Date.now();redrawInterpolatedTraffic();setWorldKpis(d);
  const total=Number(d.total_count??rows.length),tracked=Number(d.tracked_count||0),air=Number(d.airborne_count??rows.filter(x=>!x.on_ground).length),ground=Number(d.ground_count??Math.max(0,total-air));const st=$('#worldTrafficStatus');if(st){const limit=d.subscription_limited?' · PLAN LIMITÉ':'';st.textContent=`FR24 · ${tracked?fmt(tracked)+' suivis · ':''}${fmt(total)} affichés · ${fmt(air)} en vol · ${fmt(ground)} sol${limit}`;st.className='live-status '+(rows.length?(d.partial||d.subscription_limited?'warn':'ok'):'bad')}
  if(!V13_ANIM_TIMER)V13_ANIM_TIMER=setInterval(redrawInterpolatedTraffic,2200)
}
async function refreshWorldRealTraffic(force=false){
  if(!worldMap||!worldMap.loaded())return;const now=Date.now(),worldMode=worldMap.getZoom()<2.7,minDelay=worldMode?165000:22000;if(!force&&now-lastWorldTrafficAt<minDelay)return;lastWorldTrafficAt=now;
  try{let d;if(worldMode)d=await api('/api/live-traffic/world');else{const b=worldMap.getBounds();d=await api(`/api/live-traffic/box?lamin=${b.getSouth()}&lomin=${b.getWest()}&lamax=${b.getNorth()}&lomax=${b.getEast()}&limit=20000`);if(V13_WORLD_SUMMARY){d.tracked_count=V13_WORLD_SUMMARY.tracked_count;d.coverage_pct=d.tracked_count?Math.round(d.total_count/d.tracked_count*1000)/10:null}}addRealTrafficMarkers(d)}catch(e){console.warn(e);const st=$('#worldTrafficStatus');if(st){st.textContent='FR24 · dernière position conservée · mise à jour indisponible';st.className='live-status warn'}}
}
async function loadWorldSummary(){try{V13_WORLD_SUMMARY=await api('/api/integrations/fr24/world-summary');setWorldKpis({...(V13_WORLD_SUMMARY||{}),total_count:V13_WORLD_SUMMARY?.loaded_count||0})}catch{}}
function initWorldMap(){
  ensureWorldOpsOverlay();worldMap=new maplibregl.Map({container:'worldMap',style:{...SAT_STYLE,projection:{type:'globe'}},center:[10,25],zoom:1.35,pitch:20,bearing:0,maxPitch:80,antialias:true});worldMap.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');
  worldMap.on('load',async()=>{worldMap.setProjection({type:'globe'});ensureWorldTrafficLayers();await Promise.allSettled([loadMajorAirports(),addWeather(),loadWorldSummary()]);ensureNightLayer();syncWorldRoutes();syncWorldAircraft();await refreshWorldRealTraffic(true)});worldMap.on('moveend',()=>refreshWorldRealTraffic(false));worldMap.on('zoomend',()=>refreshWorldRealTraffic(true));worldMap.on('click','major-airports',e=>inspectWorldAirport(e.features[0].properties));worldMap.on('click','owned-hubs',e=>inspectWorldAirport(e.features[0].properties));setInterval(()=>{ensureNightLayer();refreshWorldRealTraffic(false)},30000)
}

// ---------- weather + METAR/TAF + real NOTAM integration diagnostics ----------
async function loadNotamsFor(icao,target='#notamListV13'){
  const box=$(target);if(box)box.innerHTML='<div class="notam-loading">Chargement des NOTAM actifs…</div>';try{const d=await api('/api/aviation/notams?icao='+encodeURIComponent(icao));if(!box)return d;if(!d.configured){box.innerHTML=`<div class="notam-config"><b>NOTAM temps réel non activés</b><span>Ajoute la variable serveur <code>AVIATION_EDGE_API_KEY</code> dans Render. Aucune clé n’est envoyée au navigateur.</span></div>`;return d}box.innerHTML=d.ok?(d.data?.length?d.data.slice(0,20).map(n=>`<article class="notam-card"><div><b>${esc(n.number||'NOTAM')}</b><span>${esc(n.location||icao)}</span></div><p>${esc(n.text||'Texte indisponible')}</p><small>${n.start?esc(String(n.start)):''}${n.end?' → '+esc(String(n.end)):''}</small></article>`).join(''):'<div class="notam-empty">Aucun NOTAM actif renvoyé pour cet aéroport.</div>'):`<div class="notam-config"><b>NOTAM temporairement indisponibles</b><span>${esc(d.message||d.reason||'Fournisseur indisponible')}</span></div>`;return d}catch(e){if(box)box.innerHTML=`<div class="notam-config"><b>NOTAM indisponibles</b><span>${esc(e.message)}</span></div>`;return null}
}
async function testIntegrations(){
  const box=$('#integrationStatus');if(!box)return;box.innerHTML='<div>Tests serveur en cours…</div>';const ident=activeHubIdent||STATE.hubs?.[0]?.ident||'LFPG',a=(STATE.hubs||[]).find(h=>h.ident===ident)?.airport,icao=String(a?.ident||ident).toUpperCase().slice(0,4),lat=a?.lat??49.0097,lon=a?.lon??2.5479;
  const rs=await Promise.allSettled([api('/api/integrations/fr24/world-summary'),api('/api/aviation/metar?icao='+encodeURIComponent(icao)),api('/api/aviation/taf?icao='+encodeURIComponent(icao)),api(`/api/weather/current?lat=${lat}&lon=${lon}`),api('/api/aviation/notam/status')]);
  const val=i=>rs[i].status==='fulfilled'?rs[i].value:{ok:false,reason:rs[i].reason?.message||'Erreur'};const f=val(0),m=val(1),t=val(2),w=val(3),n=val(4);V13_WORLD_SUMMARY=f.ok?f:V13_WORLD_SUMMARY;
  const coverage=f.coverage_pct!=null?` · couverture ${f.coverage_pct}%`:'';box.innerHTML=`<div class="${f.ok?'ok':'bad'}"><span>Flightradar24 · MONDE</span><b>${f.ok?`${fmt(f.tracked_count||0)} suivis par FR24 · ${fmt(f.loaded_count||0)} chargés · ${fmt(f.airborne_count||0)} en vol${coverage}`:`ÉCHEC · ${esc(f.reason||'indisponible')}`}</b>${f.subscription_limited?`<small>Ton plan API plafonne les positions récupérables par requête (plafond observé ≈ ${fmt(f.apparent_response_cap||0)}). Le Globe couvre le monde par zones mais ne peut pas inventer les positions que le plan ne délivre pas.</small>`:''}</div><div class="${m.ok?'ok':'bad'}"><span>METAR · AviationWeather</span><b>${m.ok?`${m.station} · ${esc(m.raw||'disponible')}`:`Indisponible · ${esc(m.reason||'')}`}</b></div><div class="${t.ok?'ok':'bad'}"><span>TAF · AviationWeather</span><b>${t.ok?`${t.station} · disponible`:`Indisponible · ${esc(t.reason||'')}`}</b></div><div class="${w.ok?'ok':'bad'}"><span>Météo générale</span><b>${w.ok?`${esc(w.source||'Open-Meteo')} · ${w.current?.temperature_2m??'—'} °C · vent ${w.current?.wind_speed_10m??'—'} kt`:'Indisponible'}</b></div><div class="${n.configured?'ok':'warn'}"><span>NOTAM mondiaux</span><b>${n.configured?`${esc(n.provider)} · connecté`:'Clé fournisseur à ajouter sur Render'}</b></div>`;setWorldKpis({...(f||{}),total_count:f.loaded_count||0});await loadNotamsFor(icao)
}

async function inspectWorldAirport(props){try{const a=await api('/api/airports/'+encodeURIComponent(props.ident));const owned=STATE.hubs.some(h=>h.ident===a.ident);$('#worldInspectorContent').innerHTML=`<span class="inspector-tag">AÉROPORT</span><h2 class="inspector-title">${esc(a.code)} · ${esc(a.name)}</h2><p class="muted">${esc(a.municipality||'')} · ${esc(a.country)}</p><div class="stat-row"><span>Pistes</span><b>${a.runway_count}</b></div><div class="stat-row"><span>Plus longue</span><b>${Math.round(a.longest_runway_ft*.3048)} m</b></div><div class="stat-row"><span>Statut</span><b>${owned?'Hub possédé':money(a.price)}</b></div><button class="secondary" id="worldNotamBtn">NOTAM actifs</button>${owned?`<button class="primary" id="goWorldHub">Ouvrir ce hub</button>`:`<button class="primary" id="buyWorldHub">Acheter comme hub</button>`}<div id="worldAirportNotams" class="world-airport-notams"></div>`;$('#worldInspector').classList.add('open');$('#worldNotamBtn')?.addEventListener('click',()=>loadNotamsFor(String(a.ident||a.code).slice(0,4),'#worldAirportNotams'));if(owned)$('#goWorldHub')?.addEventListener('click',()=>{activeHubIdent=a.ident;renderHubSelector();loadHub(a.ident);nav('hub')});else $('#buyWorldHub')?.addEventListener('click',()=>buyHub(a.ident))}catch(e){toast(e.message)}}

// ---------- Career + real eras ----------
async function renderCareer(){
  const root=$('#careerContent');if(!root||!STATE)return;root.innerHTML='<div class="empty-state"><b>Chargement de la progression…</b></div>';try{const [rd,al]=await Promise.all([api('/api/research'),api('/api/alliances')]);const p=STATE.progression||{},qs=STATE.quests?.items||[],era=rd.era||{},cur=era.current||{},next=era.next||null;
  root.innerHTML=`<section class="career-hero-v13 panel"><div class="career-rank-v13"><span>NIVEAU</span><b>${p.level||1}</b><small>${esc(p.era||cur.name||'Commandant')}</small></div><div class="career-progress-v13"><p class="eyebrow">NIVEAU JOUEUR & QUÊTES</p><h2>${fmt(p.xp_total||0)} XP</h2><div class="career-xp-track"><i style="width:${p.progress_pct||0}%"></i></div><span>${fmt(p.xp_current||0)} / ${fmt(p.xp_next||0)} XP · ${fmt(p.flights_completed||0)} rotations</span></div><div class="career-stats-v13"><div><small>FLOTTE</small><b>${STATE.aircraft?.length||0}</b></div><div><small>HUBS</small><b>${STATE.hubs?.length||0}</b></div><div><small>RÉPUTATION</small><b>${STATE.user?.reputation||0}</b></div></div></section>
  <section class="career-grid-v13"><article class="panel"><div class="section-title-row"><div><p class="eyebrow">QUÊTES QUOTIDIENNES</p><h2>Objectifs opérationnels</h2></div></div><div class="quest-list v13">${qs.map(q=>`<div class="quest-item"><div><b>${esc(q.label)}</b><small>${fmt(q.value)} / ${fmt(q.target)} · ${money(q.cash_reward)} · ${q.xp_reward} XP</small><div class="quest-progress"><i style="width:${Math.min(100,q.value/q.target*100)}%"></i></div></div><button data-career-claim="${q.code}" ${!q.complete||q.claimed?'disabled':''}>${q.claimed?'Récupéré':q.complete?'Récupérer':'En cours'}</button></div>`).join('')}</div></article>
  <article class="panel era-command-v13"><p class="eyebrow">PROCHAINES ÈRES</p><div class="era-current-v13"><span>ÈRE ${cur.order||1}</span><h2>${esc(cur.name||'Progression')}</h2><p>${esc(cur.description||'')}</p>${bonusChips(cur.bonuses||{})}</div>${next?`<div class="era-target-v13"><small>PROCHAINE : ${esc(next.name)}</small><div><span>Niveau ${era.career_level}/${next.min_level}</span><span>R&D ${era.research_total}/${next.min_research}</span></div><i><u style="width:${era.next_progress||0}%"></u></i></div>`:'<div class="era-target-v13 max">Toutes les ères sont débloquées.</div>'}<button class="primary" id="careerOpenResearch">Ouvrir l’arbre R&D</button></article></section>
  <section class="era-roadmap-v13">${(era.eras||[]).map(e=>{const state=e.order<(cur.order||1)?'done':e.order===(cur.order||1)?'current':'locked';return `<article class="era-card-v13 ${state}"><span class="era-index">${e.order}</span><div><small>${state==='done'?'DÉBLOQUÉE':state==='current'?'ÈRE ACTIVE':'À VENIR'}</small><h3>${esc(e.name)}</h3><p>${esc(e.description)}</p><div class="era-requirements">Niv. ${e.min_level} · ${e.min_research} R&D</div>${bonusChips(e.bonuses||{})}</div></article>`}).join('')}</section>${al.player_alliance?`<section class="panel career-alliance-v13"><p class="eyebrow">OBJECTIFS ALLIANCE</p><h2>[${esc(al.player_alliance.tag)}] ${esc(al.player_alliance.name)}</h2><div class="alliance-goals compact">${(al.player_alliance.goals||[]).slice(0,3).map(g=>`<div class="alliance-goal"><div><b>${esc(g.name)}</b><small>${g.progress}%</small></div><div class="goal-progress"><i style="width:${g.progress}%"></i></div></div>`).join('')}</div></section>`:''}`;
  root.querySelectorAll('[data-career-claim]').forEach(b=>b.addEventListener('click',async()=>{try{const d=await api('/api/quests/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quest_code:b.dataset.careerClaim})});toast(`Récompense : ${money(d.cash_reward)} + ${d.xp_reward} XP`);await loadState();renderCareer()}catch(e){toast(e.message)}}));$('#careerOpenResearch')?.addEventListener('click',()=>{managementTab='research';nav('management');setTimeout(()=>{document.querySelector('[data-mtab="research"]')?.click()},50)})
  }catch(e){root.innerHTML=`<div class="empty-state"><b>Progression indisponible</b><span>${esc(e.message)}</span></div>`}
}

// ---------- Special Ops premium ----------
let V13_SPECIAL_BRANCH='fire';
const V13_SPECIAL_FLEET=[
  ['CL2T','Canadair CL-415','Bombardier d’eau','/static/aircraft/real/cl415.jpg','fire'],['EC45','H145 Secours','Hélicoptère de secours','/static/aircraft/real/h145.jpg','sar'],['NH90','NH90 Caïman','Hélicoptère tactique','/static/aircraft/real/nh90.jpg','gendarmerie'],['A400','A400M Atlas','Transport stratégique','/static/aircraft/real/a400m.jpg','government'],['RFAL','Rafale','Défense / souveraineté','/static/aircraft/real/rafale.jpg','defense']
];
async function renderSpecialOps(){
  const root=$('#specialOpsContent');if(!root)return;root.innerHTML='<div class="empty-state"><b>Chargement des opérations spécialisées…</b></div>';try{const d=await api('/api/special-ops'),hubs=STATE.hubs||[],branch=d.branches.find(x=>x.code===V13_SPECIAL_BRANCH)||d.branches[0],active=(d.active_contracts||[]).filter(x=>x.status==='active'),fleetCounts={};(STATE.aircraft||[]).forEach(x=>fleetCounts[x.spec?.icao||x.type_icao]=(fleetCounts[x.spec?.icao||x.type_icao]||0)+1);
  root.innerHTML=`<section class="special-command-v13"><div class="special-command-copy"><p class="eyebrow">ACTIVITÉS SPÉCIALISÉES</p><h2>Secours, Sécurité civile & opérations stratégiques</h2><p>Construis des bases spécialisées, maintiens une flotte disponible et accepte des contrats automatisés. Chaque branche se débloque réellement avec ta progression.</p><div class="special-summary-v13"><div><small>NIVEAU</small><b>${d.level}</b></div><div><small>BASES</small><b>${d.bases.length}</b></div><div><small>MISSIONS ACTIVES</small><b>${active.length}</b></div><div><small>APPAREILS SPÉ.</small><b>${V13_SPECIAL_FLEET.reduce((s,x)=>s+(fleetCounts[x[0]]||0),0)}</b></div></div></div><div class="special-command-visual"><img src="/static/assets/civil-ops-map-crop.jpg" alt="Sécurité civile SKYLINE"></div></section>
  <div class="special-tabs-v13">${d.branches.map(b=>`<button class="${b.code===branch.code?'active':''} ${b.unlocked?'':'locked'}" data-special-tab="${b.code}"><span>${b.icon}</span>${esc(b.label.replace(/\/.*$/,''))}<small>${b.owned?'BASE ACTIVE':b.unlocked?'DISPONIBLE':'NIV. '+b.min_level}</small></button>`).join('')}</div>
  <section class="special-layout-v13"><article class="panel special-branch-detail-v13"><div><p class="eyebrow">${esc(branch.label)}</p><h2>${esc(branch.desc)}</h2><span class="special-lock-state ${branch.unlocked?'ok':'locked'}">${branch.owned?'● Base opérationnelle':branch.reason}</span></div>${branch.owned?'':branch.unlocked?`<div class="special-base-buy"><label>Hub d’implantation<select id="v13SpecialHub">${hubs.map(h=>`<option value="${h.ident}">${esc(h.airport.code)} · ${esc(h.airport.name)}</option>`).join('')}</select></label><button class="primary" id="v13BuildSpecial">Construire · ${money(branch.base_cost)}</button></div>`:`<button class="secondary" disabled>🔒 Niveau ${branch.min_level} requis</button>`}</article>
  <article class="panel"><p class="eyebrow">FLOTTE DÉDIÉE</p><div class="special-fleet-v13">${V13_SPECIAL_FLEET.filter(x=>x[4]===branch.code||branch.code==='gendarmerie'&&x[4]==='sar').map(x=>`<button class="special-plane-card-v13" data-special-plane="${x[0]}"><img src="${x[3]}" alt="${esc(x[1])}"><span><b>${esc(x[1])}</b><small>${esc(x[2])}</small><em>${fleetCounts[x[0]]||0} en flotte</em></span></button>`).join('')||'<p class="muted">La flotte de cette branche se développe dans le catalogue.</p>'}</div></article></section>
  <section class="panel special-contracts-v13"><div class="section-title-row"><div><p class="eyebrow">CONTRATS & MISSIONS</p><h2>${esc(branch.label)}</h2></div></div><div class="contract-grid v13">${d.contracts.filter(c=>c.branch===branch.code).map(c=>{const base=d.bases.find(b=>b.branch===c.branch);return `<article class="contract-card ${c.unlocked?'':'locked'}"><span class="contract-country">${esc(c.country)}</span><h3>${esc(c.title)}</h3><p>${c.required_count||1} appareil(s) · ${(c.aircraft||[]).join(' / ')} · ${c.compatible_aircraft_count||0} disponible(s)</p><div class="contract-readiness"><span>Base ${base?'✓':'✕'}</span><span>Flotte ${c.fleet_ready?'✓':'✕'}</span></div><div class="price-row"><strong>${money(c.reward)}</strong><button class="mini-btn" data-contract="${c.code}" data-base="${base?.id||''}" ${!c.unlocked||!base||!c.fleet_ready||c.active?'disabled':''}>${c.active?'MISSION ACTIVE':!c.unlocked?'Niv. '+c.min_level:!base?'Base requise':!c.fleet_ready?'Flotte requise':'Accepter'}</button></div></article>`}).join('')||'<div class="empty-state"><span>Aucun contrat pour cette branche actuellement.</span></div>'}</div></section>
  ${active.length?`<section class="panel"><p class="eyebrow">ACTIVITÉ EN COURS</p><div class="special-active-list-v13">${active.map(c=>`<div><span><b>${esc(c.title)}</b><small>${esc(c.country)} · fin ${c.ends_at?new Date(c.ends_at).toLocaleDateString('fr-FR'):'—'}</small></span><strong>${money(c.reward)}</strong></div>`).join('')}</div></section>`:''}`;
  root.querySelectorAll('[data-special-tab]').forEach(b=>b.addEventListener('click',()=>{V13_SPECIAL_BRANCH=b.dataset.specialTab;renderSpecialOps()}));$('#v13BuildSpecial')?.addEventListener('click',async()=>{try{await api('/api/special-ops/base',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({airport_ident:$('#v13SpecialHub').value,branch:branch.code})});toast('Base spécialisée construite');await loadState();renderSpecialOps()}catch(e){toast(e.message)}});root.querySelectorAll('[data-special-plane]').forEach(b=>b.addEventListener('click',()=>{marketQuery=b.dataset.specialPlane;$('#aircraftSearch').value=marketQuery;loadMarket(true);nav('market')}));root.querySelectorAll('[data-contract]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api('/api/special-ops/contract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({contract_code:btn.dataset.contract,base_id:Number(btn.dataset.base)})});toast('Mission activée · dispatch automatique');renderSpecialOps()}catch(e){toast(e.message)}}))
  }catch(e){root.innerHTML=`<div class="empty-state"><b>Opérations spécialisées indisponibles</b><span>${esc(e.message)}</span></div>`}
}

// ---------- Alliances premium + shared upgrades ----------
async function renderAlliances(){
  const root=$('#allianceContent');if(!root)return;root.innerHTML='<div class="empty-state"><b>Chargement des alliances…</b></div>';try{const d=await api('/api/alliances'),pa=d.player_alliance;
  const airlineCards=d.airline_alliances.map(a=>`<article class="airline-alliance-card ${a.joined?'joined':''}"><img src="${a.logo}" alt="${esc(a.name)}"><div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p>${bonusChips(a.bonuses)}</div><button class="${a.joined?'secondary':'primary'}" data-airline-join="${a.code}" ${a.joined||!a.eligible?'disabled':''}>${a.joined?'Membre actif':a.eligible?'Rejoindre':'Niveau '+a.min_level+' requis'}</button></article>`).join('');
  root.innerHTML=`<section class="alliance-hero-v13"><div class="alliance-hero-copy"><p class="eyebrow">ALLIANCES & ÉQUIPE</p><h2>Construire un réseau mondial ensemble</h2><p>Les économies, investissements, hubs et objectifs sont partagés. Chaque amélioration achetée par l’alliance profite automatiquement à tous ses membres.</p><div class="alliance-promise-grid"><span>⛽ Contrats carburant</span><span>♙ Formation équipages</span><span>⚙ Maintenance partagée</span><span>✈ Achats & leasing</span><span>⌁ Codeshare & lignes</span><span>♛ Salons & fidélité</span></div></div><div class="alliance-hero-image"></div></section><section class="panel"><div class="section-title-row"><div><p class="eyebrow">RÉSEAUX AÉRIENS</p><h2>Alliances internationales</h2></div></div><div class="airline-alliance-grid v13">${airlineCards}</div></section>
  ${pa?`<section class="alliance-dashboard-v13"><article class="panel alliance-command-v13"><div class="alliance-title-row"><div><p class="eyebrow">ALLIANCE DE JOUEURS</p><h2>[${esc(pa.tag)}] ${esc(pa.name)}</h2><span>${esc(pa.role)}${pa.can_manage?' · gestion autorisée':''}</span></div><span class="alliance-level-badge">NIV. ${pa.level}</span></div><div class="alliance-kpis-v13"><div><small>MEMBRES</small><b>${pa.member_count}/50</b></div><div><small>TRÉSORERIE</small><b>${money(pa.treasury)}</b></div><div><small>PAYS</small><b>${pa.network?.countries||0}</b></div><div><small>ÉCONOMIES 30 J</small><b>${money(pa.monthly_savings)}</b></div></div><div class="alliance-xp"><div><span>Progression alliance</span><b>${fmt(pa.xp)} XP${pa.maxed?' · MAX':` / ${fmt(pa.xp_next)} XP`}</b></div><i><u style="width:${pa.maxed?100:Math.max(0,Math.min(100,(pa.xp-pa.xp_floor)/Math.max(1,pa.xp_next-pa.xp_floor)*100))}%"></u></i></div><h3>Avantages cumulés pour chaque membre</h3>${bonusChips(pa.active_bonuses)}<div class="alliance-contribute-row"><input id="allianceContribution" type="number" min="10000" value="100000"><button class="primary" id="allianceContribute">Verser à la trésorerie</button><button class="danger-button" id="allianceLeave">Quitter</button></div></article>
  <article class="panel alliance-upgrades-v13"><div class="section-title-row"><div><p class="eyebrow">AMÉLIORATIONS COMMUNES</p><h2>Investir pour tous les joueurs</h2></div><small>${pa.can_manage?'Fondateur / officier':'Consultation'}</small></div><div class="alliance-upgrade-grid-v13">${(pa.upgrades||[]).map(u=>`<article class="alliance-upgrade-card ${u.unlocked?'':'locked'} ${u.maxed?'maxed':''}"><div class="alliance-upgrade-icon">${u.icon}</div><div><span>Niveau ${u.level}/${u.max_level}</span><h3>${esc(u.name)}</h3><p>${esc(u.description)}</p><div>${bonusChips(u.current_bonuses)}</div></div><button class="${u.unlocked&&!u.maxed?'primary':'secondary'}" data-alliance-upgrade="${u.code}" ${!pa.can_manage||!u.unlocked||u.maxed?'disabled':''}>${u.maxed?'MAX':!u.unlocked?'Alliance niv. '+u.min_alliance_level:money(u.next_cost)+' · améliorer'}</button></article>`).join('')}</div></article>
  <article class="panel alliance-map-panel"><header><div><p class="eyebrow">RÉSEAU MONDIAL</p><h2>Hubs, lignes & connexions membres</h2></div><span>${pa.network?.routes?.length||0} lignes · ${pa.network?.connections||0} connexions</span></header><div class="alliance-map-filters"><button class="active" data-alliance-map-filter="all">Tout</button><button data-alliance-map-filter="mine">Mes lignes</button><button data-alliance-map-filter="partners">Partenaires</button><button data-alliance-map-filter="hubs">Hubs</button><button data-alliance-map-filter="connections">Connexions</button></div><div id="allianceNetworkMap" class="alliance-network-map"></div></article>
  <article class="panel alliance-goals-panel"><p class="eyebrow">OBJECTIFS COLLECTIFS</p><h2>Semaine en cours</h2><div class="alliance-goals">${(pa.goals||[]).map(g=>`<div class="alliance-goal ${g.complete?'complete':''}"><div><b>${esc(g.name)}</b><small>${g.metric==='savings'?money(g.value):fmt(g.value)} / ${g.metric==='savings'?money(g.target):fmt(g.target)}</small></div><div class="goal-progress"><i style="width:${g.progress}%"></i></div><span>${g.progress}%</span><button class="mini-btn" data-goal-claim="${g.code}" ${!g.complete||g.claimed?'disabled':''}>${g.claimed?'Récupéré':g.complete?`+${fmt(g.xp_reward)} XP · ${money(g.cash_reward)}`:'En cours'}</button></div>`).join('')}</div></article>
  <article class="panel alliance-members-panel"><p class="eyebrow">MEMBRES & CONTRIBUTIONS</p><div class="alliance-member-table"><div class="table-head"><span>Compagnie</span><span>Passagers 30 j</span><span>Lignes</span><span>Contribution</span><span>Économies</span></div>${pa.members.map(m=>`<div class="table-row member-row-v13" data-alliance-member="${m.user_id}"><span><b>${esc(m.company_name)}</b><small>${esc(m.username)} · ${esc(m.role)}</small></span><span>${fmt(m.passengers_30d)}</span><span>${fmt(m.routes)}</span><span>${money(m.contribution)}</span><span class="profit-pos">${money(m.savings_30d)}</span>${pa.role==='founder'&&m.role!=='founder'?`<button class="mini-btn member-role-btn" data-member-role="${m.user_id}" data-role="${m.role==='officer'?'member':'officer'}">${m.role==='officer'?'Rétrograder':'Officier'}</button>`:''}</div>`).join('')}</div></article>
  <article class="panel alliance-chat"><h2>Chat alliance</h2><div class="alliance-chat-log">${pa.chat.length?pa.chat.map(m=>`<div><b>${esc(m.username)}</b><span>${esc(m.message)}</span></div>`).join(''):'<p class="muted">Aucun message.</p>'}</div><form id="allianceChatForm"><input id="allianceMessage" maxlength="500" placeholder="Message à ton alliance…"><button class="primary">Envoyer</button></form></article></section>`:`<section class="player-alliance-board v13"><article class="panel"><p class="eyebrow">CRÉER UNE ALLIANCE</p><h2>Ton réseau, tes règles</h2><p>Crée une alliance persistante, collecte une trésorerie commune et débloque des améliorations économiques pour tous les membres.</p><label>Nom<input id="newAllianceName" placeholder="Skyline Prime"></label><label>Tag<input id="newAllianceTag" maxlength="6" placeholder="SKY"></label><button class="primary" id="createAlliance">Créer · 500 000 €</button></article><article class="panel"><h2>Alliances ouvertes</h2><div class="alliance-public-list">${d.public_player_alliances.length?d.public_player_alliances.map(a=>`<div><span><b>[${esc(a.tag)}] ${esc(a.name)}</b><small>Niv. ${a.level||1} · ${a.members}/50 · ${fmt(a.xp)} XP</small></span><button class="mini-btn" data-player-join="${a.id}">Rejoindre</button></div>`).join(''):'<div class="empty-state"><span>Aucune alliance créée.</span></div>'}</div></article></section>`}`;
  root.querySelectorAll('[data-airline-join]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/alliances/airline/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({alliance_code:b.dataset.airlineJoin})});toast('Alliance aérienne rejointe · bonus actifs');await loadState();renderAlliances()}catch(e){toast(e.message)}}));$('#createAlliance')?.addEventListener('click',async()=>{try{await api('/api/alliances/player/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#newAllianceName').value,tag:$('#newAllianceTag').value})});toast('Alliance créée');await loadState();renderAlliances()}catch(e){toast(e.message)}});root.querySelectorAll('[data-player-join]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/alliances/player/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({alliance_id:Number(b.dataset.playerJoin)})});toast('Alliance rejointe');await loadState();renderAlliances()}catch(e){toast(e.message)}}));$('#allianceContribute')?.addEventListener('click',async()=>{try{await api('/api/alliances/player/contribute',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number($('#allianceContribution').value)})});toast('Contribution versée');await loadState();renderAlliances()}catch(e){toast(e.message)}});$('#allianceLeave')?.addEventListener('click',async()=>{try{await api('/api/alliances/player/leave',{method:'POST'});toast('Alliance quittée');await loadState();renderAlliances()}catch(e){toast(e.message)}});root.querySelectorAll('[data-alliance-upgrade]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/alliances/upgrades/buy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:b.dataset.allianceUpgrade})});toast('Amélioration achetée · bonus appliqué à tous les membres');await loadState();renderAlliances()}catch(e){toast(e.message)}}));root.querySelectorAll('[data-member-role]').forEach(b=>b.addEventListener('click',async e=>{e.stopPropagation();try{await api('/api/alliances/member/role',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_id:Number(b.dataset.memberRole),role:b.dataset.role})});toast('Rôle mis à jour');renderAlliances()}catch(e){toast(e.message)}}));root.querySelectorAll('[data-goal-claim]').forEach(b=>b.addEventListener('click',async()=>{try{const out=await api('/api/alliances/goals/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({goal_code:b.dataset.goalClaim})});toast(`Objectif · +${fmt(out.reward.xp)} XP · ${money(out.reward.cash)}`);renderAlliances()}catch(e){toast(e.message)}}));$('#allianceChatForm')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/alliances/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:$('#allianceMessage').value})});renderAlliances()}catch(err){toast(err.message)}});if(pa){setTimeout(()=>initAllianceNetworkMap(pa),0);root.querySelectorAll('[data-alliance-map-filter]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-alliance-map-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');setAllianceNetworkFilter(b.dataset.allianceMapFilter)}));root.querySelectorAll('[data-alliance-member]').forEach(b=>b.addEventListener('click',e=>{if(e.target.closest('.member-role-btn'))return;setAllianceNetworkFilter('member',Number(b.dataset.allianceMember));allianceMap?.resize()}))}
  }catch(e){root.innerHTML=`<div class="empty-state"><b>Alliances indisponibles</b><span>${esc(e.message)}</span></div>`}
}

// OPS: add NOTAM workspace dynamically so the old technical placeholder disappears.
function ensureOpsV13(){const ops=document.querySelector('[data-view="ops"] .ops-grid');if(!ops||ops.querySelector('.notam-workspace-v13'))return;const old=[...ops.querySelectorAll('p.muted')].find(p=>p.textContent.includes('NOTAM')&&p.textContent.includes('fournisseur'));old?.remove();const card=document.createElement('article');card.className='panel notam-workspace-v13';card.innerHTML=`<div class="section-title-row"><div><p class="eyebrow">NOTAM TEMPS RÉEL</p><h2>Avis opérationnels</h2></div><button class="secondary" id="reloadNotamsV13">Actualiser</button></div><p class="muted">Source serveur authentifiée. Les NOTAM ne sont jamais inventés par le jeu.</p><div id="notamListV13"></div>`;ops.appendChild(card);$('#reloadNotamsV13')?.addEventListener('click',()=>{const ident=activeHubIdent||STATE.hubs?.[0]?.ident||'LFPG';loadNotamsFor(String(ident).slice(0,4))});}

// Hub locked state wording: server checks level + prerequisites + money.
const _v13RenderHubManagement=renderHubManagement;
renderHubManagement=async function(ident,tab=hubManagementTab){await _v13RenderHubManagement(ident,tab);document.querySelectorAll('.hub-upgrade-card.locked').forEach(card=>{card.setAttribute('aria-disabled','true')})};

// Navigation hook for new panels.
const _v13Nav=nav;
nav=function(name){_v13Nav(name);if(name==='ops'){setTimeout(()=>{ensureOpsV13();testIntegrations()},20)}if(name==='world'){setTimeout(()=>{ensureWorldOpsOverlay();loadWorldSummary()},100)}};

// ---------- INITIALISE v1.3 ----------
ensureOpsV13();
loadState().then(()=>loadMarket(true));setInterval(loadState,12000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('/static/sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});
